        int ar = ArmFor(mode);
        if (ar != 0) { Disarm(ar); return ar; }
        var target = new TaskOptions();
        // Step a2 (ii): one GCHandle per instance, its Target set for this decode.
        if (!_th.IsAllocated) _th = GCHandle.Alloc(null);
        _th.Target = target;
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                // (NULL, 0) is never handed to the core: an empty buffer is a valid pointer and 0.
                byte* b = len == 0 ? one : b0;
                _drun->Target = GCHandle.ToIntPtr(_th);
                _drun->Buf = b;
                _fwd++;
                rc = Abi.ak_decode_TaskOptions(_dctx, _drun, b, (nuint)len, Vt);
            }
        }
        finally { _th.Target = null; rc = Disarm(rc); }
        if (rc < 0) return rc;
        result = target;
        return 0;
    }

    /// D21 s8 attribution (HARNESS ONLY): the same push decode through another vtable.
    /// kind 0 `parse`: every callback null but `new_<slot>` (NewZero: the core skips a non-leaf
    /// element whose `new_` is null), utf8_skip all bits (as the reference); kind 1 `noop`:
    /// every callback G.Noop (new_: NewZero); kind 2 `parse-validate`: kind 0 with utf8_skip 0
    /// (the core validates every string).
    public static readonly ak_dvt_TaskOptions* VtParse = MakeVtAttr(0), VtNoop = MakeVtAttr(1), VtParseValidate = MakeVtAttr(2);
    private static ak_dvt_TaskOptions* MakeVtAttr(int kind)
    {
        var v = (ak_dvt_TaskOptions*)NativeMemory.AllocZeroed((nuint)sizeof(ak_dvt_TaskOptions));
        v->utf8_skip = kind == 2 ? 0 : AkUtf8Skip.TaskOptions_ALL;
        if (kind == 1) *(void**)&v->apply = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_options = G.NoopPtr;
        return v;
    }
    /// D21 s8 attribution (HARNESS ONLY): DecodeArmed through `vt`; the graph is the bare
    /// root (the callbacks build nothing) and buffers the callbacks did not take are not
    /// UNDELIVERED here (the arena rewinds at the next decode).
    public int DecodeVt(byte[] src, int len, bool retain, ak_dvt_TaskOptions* vt)
    {
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        if (!_th.IsAllocated) _th = GCHandle.Alloc(null);
        int rc;
        fixed (byte* b0 = src)
        fixed (byte* one = One)
        {
            byte* b = len == 0 ? one : b0;
            _drun->Target = GCHandle.ToIntPtr(_th);
            _drun->Buf = b;
            rc = Abi.ak_decode_TaskOptions(_dctx, _drun, b, (nuint)len, vt);
        }
        rc = Disarm(rc);
        return rc == UNDELIVERED ? 0 : rc;
    }
    /// D21 s8 attribution (HARNESS ONLY): the pull family's parse alone (no replay).
    public int ParseOnly(byte[] src, int len, bool retain)
    {
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        int rc;
        fixed (byte* b0 = src)
        fixed (byte* one = One)
            rc = Abi.ak_parse_TaskOptions(_dctx, len == 0 ? one : b0, (nuint)len);
        rc = Disarm(rc);
        return rc == UNDELIVERED ? 0 : rc;
    }

    /// ABI v1 7.1's PULL family: parse into the context's record stream (no reverse
    /// call but grow), then replay it with the same group readers the push callbacks
    /// use. The context is armed exactly as for push.
    public TaskOptions Pull(byte[] src, int len) { int rc = TryPull(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core parse failed: {rc}"); return t; }

    public int TryPull(byte[] src, int len, bool retain, out TaskOptions result)
    {
        result = null;
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        var t = new TaskOptions();
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                byte* b = len == 0 ? one : b0;
                _fwd++;
                rc = Abi.ak_parse_TaskOptions(_dctx, b, (nuint)len);
                if (rc >= 0)
                {
                    byte* recs; nuint rlen;
                    _fwd++;
                    rc = Abi.ak_bdr_ptr(_dctx, &recs, &rlen);
                    if (rc == 0) { try { Replay(t, b, recs, (int)rlen); } catch (DecoderFallbackException) { rc = Abi.AK_ERR_TRANSCODE; } }
                }
            }
        }
        finally { rc = Disarm(rc); }
        if (rc < 0) return rc;
        result = t;
        return 0;
    }

    private const uint OP_APPLY = 1, OP_ADD = 2, OP_NEW = 3, OP_APPLY_ELEM = 4;   // ak_bdr_rec.op
    private static void Replay(TaskOptions t, byte* b, byte* p, int len)
    {
        int at = 0;
        while (len - at >= sizeof(ak_bdr_rec))
        {
            ref var r = ref *(ak_bdr_rec*)(p + at);
            byte* body = p + at + sizeof(ak_bdr_rec);
            at += sizeof(ak_bdr_rec) + (int)r.bytes;
            uint outer = r.slot >> 16, inner = r.slot & 0xFFFF;
            switch (r.op)
            {
                case OP_APPLY: G.D_TaskOptions(ref *(ak_dfix_TaskOptions*)body, t, b); break;
                case OP_ADD when outer == 0 && inner == 1:   // a root-level run
                {
                    var xs = (ak_dfix_TaskOptionsOptionsEntry*)body; var lst = t.Options;
                    lst.EnsureCapacity(lst.Count + (int)r.n);   // step 9a: the run's count is known
                    // plan: a duplicate key replaces the earlier value.
                    for (int i = 0; i < (int)r.n; i++) lst[G.Str(b, xs[i].key)] = G.Str(b, xs[i].value);
                    break;
                }
                default: break;
            }
        }
    }

    /// FIX-PLAN D23: the FSM decode family. ak_fsm_begin_TaskOptions returns the first
    /// event, ak_fsm_next_TaskOptions each next one, each RETURNING the event's op (>
    /// 0; the root APPLY is the last, the end) or an error (< 0); every event is
    /// consumed (FsmDispatch) before the next call, which may overwrite its payload.
    /// One `fixed` spans begin and every next (the core holds spans into the input
    /// until the end event). Arming, Disarm, retain ownership and the failure path are
    /// pull's; a failed decode's partial object is discarded.
    public TaskOptions Fsm(byte[] src, int len) { int rc = TryFsm(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core FSM decode failed: {rc}"); return t; }
    /// D23: the FSM's own D20 mask (every bit: G.Str validates), native, copied by its setter
    /// (ak_fsm_set_pvt_<Root>) once, when EnsureDec creates the context.
    private static readonly ak_pvt_TaskOptions* FsmPvt = MakeFsmPvt();
    private static ak_pvt_TaskOptions* MakeFsmPvt() { var v = (ak_pvt_TaskOptions*)NativeMemory.AllocZeroed((nuint)sizeof(ak_pvt_TaskOptions)); v->utf8_skip = AkUtf8Skip.TaskOptions_ALL; return v; }

    public int TryFsm(byte[] src, int len, bool retain, out TaskOptions result)
    {
        result = null;
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        var t = new TaskOptions();
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                byte* b = len == 0 ? one : b0;
                ak_fsm_ev ev;
                _fwd++;
                int op = Abi.ak_fsm_begin_TaskOptions(_dctx, b, (nuint)len, &ev);
                try
                {
                    while (op > 0)
                    {
                        if (op == (int)Abi.AK_BDR_APPLY)
                        {
                            // The root group: always the last event, the end.
                            G.D_TaskOptions(ref *(ak_dfix_TaskOptions*)ev.data, t, b);
                            break;
                        }
                        FsmDispatch(t, b, (uint)op, &ev);
                        _fwd++;
                        op = Abi.ak_fsm_next_TaskOptions(_dctx, &ev);
                    }
                    rc = op < 0 ? op : 0;
                }
                catch (DecoderFallbackException) { rc = Abi.AK_ERR_TRANSCODE; }
            }
        }
        finally { rc = Disarm(rc); }
        if (rc < 0) return rc;   // the partial object is dropped
        result = t;
        return 0;
    }

    /// D23: one non-final event, `op` the call's return (NEW, ADD, APPLY_ELEM; the root APPLY is the end event,
    /// handled by TryFsm). slot = outer << 16 | inner, pull's numbering: a root-level run
    /// is (0, slot), a non-leaf slot's element is (slot, 0) and its inner runs (slot, inner).
    private static void FsmDispatch(TaskOptions t, byte* b, uint op, ak_fsm_ev* ev)
    {
        byte* d = (byte*)ev->data;
        switch (op)
        {
            case Abi.AK_BDR_ADD:
                switch (ev->slot)
                {
                    case 1u:   // a root-level run
                    {
                        var xs = (ak_dfix_TaskOptionsOptionsEntry*)d; var lst = t.Options; int n = (int)ev->n;
                        lst.EnsureCapacity(lst.Count + n);
                        for (int i = 0; i < n; i++) lst[G.Str(b, xs[i].key)] = G.Str(b, xs[i].value);
                        return;
                    }
                }
                return;
        }
    }

    public long PullFootprint() => _dctx == IntPtr.Zero ? 0 : (long)Abi.ak_bdr_footprint(_dctx);
    public AkCounters EncCounters() { AkCounters c; Abi.ak_enc_counters(_ctx, &c); return c; }
    public void EncCountersReset() => Abi.ak_enc_counters_reset(_ctx);
    public AkCounters DecCounters() { AkCounters c; if (_dctx == IntPtr.Zero) return default; Abi.ak_dec_counters(_dctx, &c); return c; }
    public void DecCountersReset() { if (_dctx != IntPtr.Zero) Abi.ak_dec_counters_reset(_dctx); }

    public void Dispose()
    {
        if (_ctx != IntPtr.Zero) { Abi.ak_enc_ctx_free(_ctx); _ctx = IntPtr.Zero; }
        if (_dctx != IntPtr.Zero) { Abi.ak_dec_ctx_free(_dctx); _dctx = IntPtr.Zero; }
        if (_th.IsAllocated) _th.Free();
        _st.Dispose();
        if (_run != null)
        {
            NativeMemory.Free(_run->S_options);
            NativeMemory.Free(_run); _run = null;
        }
        if (_drun != null) { NativeMemory.Free(_drun); _drun = null; }
    }
}

[StructLayout(LayoutKind.Sequential)]
public unsafe struct Run_TaskOutput
{
    public int Chunk;
    public int Retain;
}

/// core-ffi for `TaskOutput`: every group, slot and entry point from the plan.
public sealed unsafe class CoreFfi_TaskOutput : IDisposable
{
    private IntPtr _ctx, _dctx;
    private readonly Stage _st;
    private Run_TaskOutput* _run;
    private DecRun* _drun;
    public int Chunk;
    /// Counted where each crossing happens (R5). Static: an [UnmanagedCallersOnly]
