    private static ak_pvt_TaskOutput* MakePvt() { var v = (ak_pvt_TaskOutput*)NativeMemory.AllocZeroed((nuint)sizeof(ak_pvt_TaskOutput)); v->utf8_skip = AkUtf8Skip.TaskOutput_ALL; return v; }
