        Abi.ak_enc_reset(_ctx);
        _st.Reset();
        int __d = Stage.Defer;   // E1R / E1C: read once; the default path tests this local only
        long __mk0 = 0, __pt0 = 0;
        if (__d != 0) { __mk0 = Stage.Marked; __pt0 = Stage.Patched; }   // this encode's marks and patches
        _run->Chunk = Chunk;
        if (retain) throw new NotSupportedException("unknown fields are compiled out of this build (WP5 step 10): no ak_uencode");
        {
            var lst = src.Ticks;
            int n = lst == null ? 0 : lst.Count;
            _run->N_ticks = n;
            Arr.Ensure(ref _run->S_ticks, ref _cap_ticks, n, sizeof(long));
            for (int i = 0; i < n; i++)
            {
                ((long*)_run->S_ticks)[i] = lst[i];
            }
        }
        {
            var lst = src.Values;
            int n = lst == null ? 0 : lst.Count;
            _run->N_values = n;
            Arr.Ensure(ref _run->S_values, ref _cap_values, n, sizeof(double));
            for (int i = 0; i < n; i++)
            {
                ((double*)_run->S_values)[i] = lst[i];
            }
        }
        {
            var lst = src.Codes;
            int n = lst == null ? 0 : lst.Count;
            _run->N_codes = n;
            Arr.Ensure(ref _run->S_codes, ref _cap_codes, n, sizeof(int));
            for (int i = 0; i < n; i++)
            {
                ((int*)_run->S_codes)[i] = lst[i];
            }
        }
        {
            var lst = src.Flags;
            int n = lst == null ? 0 : lst.Count;
            _run->N_flags = n;
            Arr.Ensure(ref _run->S_flags, ref _cap_flags, n, sizeof(byte));
            for (int i = 0; i < n; i++)
            {
                ((byte*)_run->S_flags)[i] = (byte)(lst[i] ? 1 : 0);
            }
        }
        {
            var lst = src.Statuses;
            int n = lst == null ? 0 : lst.Count;
            _run->N_statuses = n;
            Arr.Ensure(ref _run->S_statuses, ref _cap_statuses, n, sizeof(int));
            for (int i = 0; i < n; i++)
            {
                ((int*)_run->S_statuses)[i] = (int)lst[i];
            }
        }
        var vt = new ak_evt_MetricsBatch
        {
            loop_ticks = &Loop_ticks,
            loop_values = &Loop_values,
            loop_codes = &Loop_codes,
            loop_flags = &Loop_flags,
            loop_statuses = &Loop_statuses,
        };
        nint rc;
        {
            var fix = new ak_efix_MetricsBatch();
            G.E_MetricsBatch(ref fix, src, _st);
            if (!call) return 0;
            _fwd++;
            if (__d != 0) { if (Stage.Marked == __mk0) __d = 0; else { _pinSrc = src; Stage.DeferNow = __d; } }
            if (__d == 0) rc = Abi.ak_encode_MetricsBatch(_run, _ctx, &vt, &fix);
            else rc = __d == 1 ? RootPinR_e(_run, _ctx, &vt, &fix, src) : RootPinH_e(_run, _ctx, &vt, &fix, src);
        }
        _st.ReleasePins();   // D21 E1: the core has copied every pinned string
        if (__d != 0)
        {
            Stage.DeferNow = 0;   // the next encode on this thread starts from the default
            _pinSrc = null;
            // E1R / E1C: every mark the fill left was patched by a frame before the core read it.
            if (Stage.Marked - __mk0 != Stage.Patched - __pt0 && rc >= 0) rc = Abi.AK_ERR_HOST;
        }
        if (rc < 0) return (int)rc;
        if (_keep) return 0;   // EncodeInto: the output stays in the context (the move path)
        byte* bp; nuint blen;
        int tk = Abi.ak_enc_take(_ctx, &bp, &blen);
        if (tk != 0) return tk;
        outPtr = bp; outLen = (int)blen;
        return 0;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct DecRun { public IntPtr Target; public byte* Buf; }

    private static MetricsBatch Tgt(void* obj) => (MetricsBatch)GCHandle.FromIntPtr(((DecRun*)obj)->Target).Target;

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void ApplyRoot(IntPtr ctx, void* obj, ak_dfix_MetricsBatch* fix)
    {
        _rev++;
        try { if (G.PlantHostFail == 1) throw new InvalidOperationException("planted host failure (apply)"); G.D_MetricsBatch(ref *fix, Tgt(obj), ((DecRun*)obj)->Buf); }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_ticks(IntPtr ctx, void* obj, long token, long* xs, int n)
    {
