    private static readonly byte[] One = new byte[1];

    /// WP5 step 10: this build has unknown fields COMPILED OUT (no options, no resets).
    public const bool UnknownCompiledOut = true;
    public const int UNDELIVERED = -1001;   // never returned by this build
    public int Undelivered => 0;
    public long ResetCalls => 0;

    private void EnsureDec()
    {
        if (_dctx != IntPtr.Zero) return;
        _dctx = Abi.ak_dec_ctx_new_MetricsBatch();   // rule 6: bound to this root; no options exist
        if (_dctx == IntPtr.Zero) throw new InvalidOperationException("ak_dec_ctx_new_MetricsBatch returned NULL");
        // D20: the pull family's bits, copied into this root-bound context (every bit: G.Str validates).
        int sp = Abi.ak_dec_set_pvt_MetricsBatch(_dctx, Pvt);   // step 5b: the root's one native pvt
        if (sp != 0) throw new InvalidOperationException("ak_dec_set_pvt_MetricsBatch: " + sp);
        // D23 / D24: the FSM's own D20 mask, copied once into the context when it is created (set
        // lazily on the first FSM decode, it made one count row depend on which thread decoded).
        int fp = Abi.ak_fsm_set_pvt_MetricsBatch(_dctx, FsmPvt);
        if (fp != 0) throw new InvalidOperationException("ak_fsm_set_pvt_MetricsBatch: " + fp);
        _drun = (DecRun*)NativeMemory.AllocZeroed((nuint)sizeof(DecRun));
    }

    private int ArmFor(int mode) => mode == -2 ? 0 : throw new NotSupportedException("unknown fields are compiled out of this build (WP5 step 10)");
    private int Disarm(int rc) => rc;

    public MetricsBatch Decode(byte[] src, int len) { int rc = TryDecode(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core decode failed: {rc}"); return t; }

    /// The core's code (< 0) on failure; the output is then unspecified and discarded (R-G6).
    public int TryDecode(byte[] src, int len, bool retain, out MetricsBatch result) => DecodeArmed(src, len, retain ? -1 : -2, out result);

    /// Step 5b (owner, 2026-10-04): the push vtable, built ONCE per root and kept in native
    /// memory (NativeMemory.Alloc, never freed: one per root for the process), so no decode
    /// writes it and the GC cannot move it. Not a static field of the struct type taken by
    /// address: a non-primitive struct static lives in a boxed object on the GC heap, which
    /// compaction may move, so its address is not stable without a pin. The core only reads
    /// the vtable during the call.
    private static readonly ak_dvt_MetricsBatch* Vt = MakeVt();
    private static ak_dvt_MetricsBatch* MakeVt()
    {
        var v = (ak_dvt_MetricsBatch*)NativeMemory.AllocZeroed((nuint)sizeof(ak_dvt_MetricsBatch));
        v->utf8_skip = AkUtf8Skip.MetricsBatch_ALL;   // D20: every bit set, G.Str validates (strict)
        v->apply = &ApplyRoot;
        v->add_ticks = &Add_ticks;
        v->add_values = &Add_values;
        v->add_codes = &Add_codes;
        v->add_flags = &Add_flags;
        v->add_statuses = &Add_statuses;
        return v;
    }
    /// Step 5b: the pull family's bits, once per root in native memory (the setter copies them).
    private static readonly ak_pvt_MetricsBatch* Pvt = MakePvt();
    private static ak_pvt_MetricsBatch* MakePvt() { var v = (ak_pvt_MetricsBatch*)NativeMemory.AllocZeroed((nuint)sizeof(ak_pvt_MetricsBatch)); v->utf8_skip = AkUtf8Skip.MetricsBatch_ALL; return v; }
    private GCHandle _th;
    private int DecodeArmed(byte[] src, int len, int mode, out MetricsBatch result)
    {
        result = null;
        EnsureDec();
        // Step a2 (i): no ak_dec_err_reset / ak_dec_err: ak_decode_* clears the context's
        // sticky slot on entry and returns it (a host failure reported through ak_fail
        // from a reverse call included), so its return value carries every error.
        int ar = ArmFor(mode);
        if (ar != 0) { Disarm(ar); return ar; }
        var target = new MetricsBatch();
        // Step a2 (ii): one GCHandle per instance, its Target set for this decode.
        if (!_th.IsAllocated) _th = GCHandle.Alloc(null);
        _th.Target = target;
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                // (NULL, 0) is never handed to the core: an empty buffer is a valid pointer and 0.
                byte* b = len == 0 ? one : b0;
                _drun->Target = GCHandle.ToIntPtr(_th);
                _drun->Buf = b;
                _fwd++;
                rc = Abi.ak_decode_MetricsBatch(_dctx, _drun, b, (nuint)len, Vt);
            }
        }
        finally { _th.Target = null; rc = Disarm(rc); }
        if (rc < 0) return rc;
        result = target;
        return 0;
    }

    /// D21 s8 attribution (HARNESS ONLY): the same push decode through another vtable.
    /// kind 0 `parse`: every callback null but `new_<slot>` (NewZero: the core skips a non-leaf
    /// element whose `new_` is null), utf8_skip all bits (as the reference); kind 1 `noop`:
    /// every callback G.Noop (new_: NewZero); kind 2 `parse-validate`: kind 0 with utf8_skip 0
    /// (the core validates every string).
    public static readonly ak_dvt_MetricsBatch* VtParse = MakeVtAttr(0), VtNoop = MakeVtAttr(1), VtParseValidate = MakeVtAttr(2);
    private static ak_dvt_MetricsBatch* MakeVtAttr(int kind)
    {
        var v = (ak_dvt_MetricsBatch*)NativeMemory.AllocZeroed((nuint)sizeof(ak_dvt_MetricsBatch));
        v->utf8_skip = kind == 2 ? 0 : AkUtf8Skip.MetricsBatch_ALL;
        if (kind == 1) *(void**)&v->apply = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_ticks = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_values = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_codes = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_flags = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_statuses = G.NoopPtr;
        return v;
    }
    /// D21 s8 attribution (HARNESS ONLY): DecodeArmed through `vt`; the graph is the bare
    /// root (the callbacks build nothing) and buffers the callbacks did not take are not
    /// UNDELIVERED here (the arena rewinds at the next decode).
    public int DecodeVt(byte[] src, int len, bool retain, ak_dvt_MetricsBatch* vt)
    {
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        if (!_th.IsAllocated) _th = GCHandle.Alloc(null);
        int rc;
        fixed (byte* b0 = src)
        fixed (byte* one = One)
        {
            byte* b = len == 0 ? one : b0;
            _drun->Target = GCHandle.ToIntPtr(_th);
            _drun->Buf = b;
            rc = Abi.ak_decode_MetricsBatch(_dctx, _drun, b, (nuint)len, vt);
        }
        rc = Disarm(rc);
        return rc == UNDELIVERED ? 0 : rc;
    }
    /// D21 s8 attribution (HARNESS ONLY): the pull family's parse alone (no replay).
    public int ParseOnly(byte[] src, int len, bool retain)
    {
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        int rc;
        fixed (byte* b0 = src)
        fixed (byte* one = One)
            rc = Abi.ak_parse_MetricsBatch(_dctx, len == 0 ? one : b0, (nuint)len);
        rc = Disarm(rc);
        return rc == UNDELIVERED ? 0 : rc;
    }

    /// ABI v1 7.1's PULL family: parse into the context's record stream (no reverse
    /// call but grow), then replay it with the same group readers the push callbacks
    /// use. The context is armed exactly as for push.
    public MetricsBatch Pull(byte[] src, int len) { int rc = TryPull(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core parse failed: {rc}"); return t; }

    public int TryPull(byte[] src, int len, bool retain, out MetricsBatch result)
    {
        result = null;
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        var t = new MetricsBatch();
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                byte* b = len == 0 ? one : b0;
                _fwd++;
                rc = Abi.ak_parse_MetricsBatch(_dctx, b, (nuint)len);
                if (rc >= 0)
                {
                    byte* recs; nuint rlen;
                    _fwd++;
                    rc = Abi.ak_bdr_ptr(_dctx, &recs, &rlen);
                    if (rc == 0) { try { Replay(t, b, recs, (int)rlen); } catch (DecoderFallbackException) { rc = Abi.AK_ERR_TRANSCODE; } }
                }
            }
        }
        finally { rc = Disarm(rc); }
        if (rc < 0) return rc;
        result = t;
        return 0;
    }

    private const uint OP_APPLY = 1, OP_ADD = 2, OP_NEW = 3, OP_APPLY_ELEM = 4;   // ak_bdr_rec.op
    private static void Replay(MetricsBatch t, byte* b, byte* p, int len)
    {
        int at = 0;
        while (len - at >= sizeof(ak_bdr_rec))
        {
            ref var r = ref *(ak_bdr_rec*)(p + at);
            byte* body = p + at + sizeof(ak_bdr_rec);
            at += sizeof(ak_bdr_rec) + (int)r.bytes;
            uint outer = r.slot >> 16, inner = r.slot & 0xFFFF;
            switch (r.op)
            {
                case OP_APPLY: G.D_MetricsBatch(ref *(ak_dfix_MetricsBatch*)body, t, b); break;
                case OP_ADD when outer == 0 && inner == 1:   // a root-level run
                {
                    var xs = (long*)body; var lst = t.Ticks;
                    lst.EnsureCapacity(lst.Count + (int)r.n);   // step 9a: the run's count is known
                    for (int i = 0; i < (int)r.n; i++) lst.Add(xs[i]);
                    break;
                }
                case OP_ADD when outer == 0 && inner == 2:   // a root-level run
                {
                    var xs = (double*)body; var lst = t.Values;
                    lst.EnsureCapacity(lst.Count + (int)r.n);   // step 9a: the run's count is known
                    for (int i = 0; i < (int)r.n; i++) lst.Add(xs[i]);
                    break;
                }
                case OP_ADD when outer == 0 && inner == 3:   // a root-level run
                {
                    var xs = (int*)body; var lst = t.Codes;
                    lst.EnsureCapacity(lst.Count + (int)r.n);   // step 9a: the run's count is known
                    for (int i = 0; i < (int)r.n; i++) lst.Add(xs[i]);
                    break;
                }
                case OP_ADD when outer == 0 && inner == 4:   // a root-level run
                {
                    var xs = (byte*)body; var lst = t.Flags;
                    lst.EnsureCapacity(lst.Count + (int)r.n);   // step 9a: the run's count is known
                    for (int i = 0; i < (int)r.n; i++) lst.Add((xs[i] != 0));
                    break;
                }
                case OP_ADD when outer == 0 && inner == 5:   // a root-level run
                {
                    var xs = (int*)body; var lst = t.Statuses;
                    lst.EnsureCapacity(lst.Count + (int)r.n);   // step 9a: the run's count is known
                    for (int i = 0; i < (int)r.n; i++) lst.Add((TaskStatus)xs[i]);
                    break;
                }
                default: break;
            }
        }
    }

    /// FIX-PLAN D23: the FSM decode family. ak_fsm_begin_MetricsBatch returns the first
    /// event, ak_fsm_next_MetricsBatch each next one, each RETURNING the event's op (>
    /// 0; the root APPLY is the last, the end) or an error (< 0); every event is
    /// consumed (FsmDispatch) before the next call, which may overwrite its payload.
    /// One `fixed` spans begin and every next (the core holds spans into the input
    /// until the end event). Arming, Disarm, retain ownership and the failure path are
    /// pull's; a failed decode's partial object is discarded.
    public MetricsBatch Fsm(byte[] src, int len) { int rc = TryFsm(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core FSM decode failed: {rc}"); return t; }
    /// D23: the FSM's own D20 mask (every bit: G.Str validates), native, copied by its setter
    /// (ak_fsm_set_pvt_<Root>) once, when EnsureDec creates the context.
    private static readonly ak_pvt_MetricsBatch* FsmPvt = MakeFsmPvt();
    private static ak_pvt_MetricsBatch* MakeFsmPvt() { var v = (ak_pvt_MetricsBatch*)NativeMemory.AllocZeroed((nuint)sizeof(ak_pvt_MetricsBatch)); v->utf8_skip = AkUtf8Skip.MetricsBatch_ALL; return v; }

    public int TryFsm(byte[] src, int len, bool retain, out MetricsBatch result)
    {
        result = null;
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        var t = new MetricsBatch();
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                byte* b = len == 0 ? one : b0;
                ak_fsm_ev ev;
                _fwd++;
                int op = Abi.ak_fsm_begin_MetricsBatch(_dctx, b, (nuint)len, &ev);
                try
                {
                    while (op > 0)
                    {
                        if (op == (int)Abi.AK_BDR_APPLY)
                        {
                            // The root group: always the last event, the end.
                            G.D_MetricsBatch(ref *(ak_dfix_MetricsBatch*)ev.data, t, b);
                            break;
                        }
                        FsmDispatch(t, b, (uint)op, &ev);
                        _fwd++;
                        op = Abi.ak_fsm_next_MetricsBatch(_dctx, &ev);
                    }
                    rc = op < 0 ? op : 0;
                }
                catch (DecoderFallbackException) { rc = Abi.AK_ERR_TRANSCODE; }
            }
        }
        finally { rc = Disarm(rc); }
        if (rc < 0) return rc;   // the partial object is dropped
        result = t;
        return 0;
    }

    /// D23: one non-final event, `op` the call's return (NEW, ADD, APPLY_ELEM; the root APPLY is the end event,
    /// handled by TryFsm). slot = outer << 16 | inner, pull's numbering: a root-level run
    /// is (0, slot), a non-leaf slot's element is (slot, 0) and its inner runs (slot, inner).
    private static void FsmDispatch(MetricsBatch t, byte* b, uint op, ak_fsm_ev* ev)
    {
        byte* d = (byte*)ev->data;
        switch (op)
        {
            case Abi.AK_BDR_ADD:
                switch (ev->slot)
                {
                    case 1u:   // a root-level run
                    {
                        var xs = (long*)d; var lst = t.Ticks; int n = (int)ev->n;
                        lst.EnsureCapacity(lst.Count + n);
                        for (int i = 0; i < n; i++) lst.Add(xs[i]);
                        return;
                    }
                    case 2u:   // a root-level run
                    {
                        var xs = (double*)d; var lst = t.Values; int n = (int)ev->n;
                        lst.EnsureCapacity(lst.Count + n);
                        for (int i = 0; i < n; i++) lst.Add(xs[i]);
                        return;
                    }
                    case 3u:   // a root-level run
                    {
                        var xs = (int*)d; var lst = t.Codes; int n = (int)ev->n;
                        lst.EnsureCapacity(lst.Count + n);
                        for (int i = 0; i < n; i++) lst.Add(xs[i]);
                        return;
                    }
                    case 4u:   // a root-level run
                    {
                        var xs = (byte*)d; var lst = t.Flags; int n = (int)ev->n;
                        lst.EnsureCapacity(lst.Count + n);
                        for (int i = 0; i < n; i++) lst.Add((xs[i] != 0));
                        return;
                    }
                    case 5u:   // a root-level run
                    {
                        var xs = (int*)d; var lst = t.Statuses; int n = (int)ev->n;
                        lst.EnsureCapacity(lst.Count + n);
                        for (int i = 0; i < n; i++) lst.Add((TaskStatus)xs[i]);
                        return;
                    }
                }
