                if (__g->opt_label.data == Stage.PinPending) { __g->opt_label.data = Stage.PinChunk(__e.OptLabel); }
                if (__g->body_as_text.data == Stage.PinPending) { __g->body_as_text.data = Stage.PinChunk((__e.BodyCase == ProbeBodyCase.AsText ? (__e.AsText ?? "") : null)); }
            }
        }
        Stage.BeforeChunkCall(__h);
        _fwd++;
        int rc = Abi.ak_elem_Probe(ctx, (ak_efix_Probe*)((ak_efix_Probe*)run->S_probes + off), k);
        Stage.ReleaseChunk(__h);
        return rc;
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static int Loop_probes(IntPtr ctx, void* obj, long token)
    {
        _rev++;
        try
        {
            var run = (Run_ListProbeResponse*)obj;
            int n = run->N_probes;
            if (n == 0) return 0;
            int chunk = run->Chunk <= 0 ? n : run->Chunk;
            int d = Stage.DeferNow;
            if (d != 0 && chunk > Stage.PinK) chunk = Stage.PinK;
            for (int off = 0; off < n; off += chunk)
            {
                int k = n - off; if (k > chunk) k = chunk;
                if (d != 0)
                {
                    int rp = d == 1 ? Rec_probes(ctx, run, _pinSrc.Probes, off, k, 0) : ChunkH_probes(ctx, run, _pinSrc.Probes, off, k);
                    Stage.AfterChunk();
                    if (rp < 0) return rp;
                    continue;
                }
                _fwd++;
                int rc = Abi.ak_elem_Probe(ctx, (ak_efix_Probe*)((ak_efix_Probe*)run->S_probes + off), k);
                if (rc < 0) return rc;
            }
            return 0;
        }
        catch { return Abi.AK_ERR_HOST; }
    }

    public int Fill(ListProbeResponse src) { Go(src, false, false, out _, out _); return 0; }
    public void Encode(ListProbeResponse src, out byte* p, out int len) { int rc = Go(src, false, true, out p, out len); if (rc < 0) throw new InvalidOperationException($"core encode failed: {rc}"); }
    public int TryEncode(ListProbeResponse src, bool retain, out byte* p, out int len) => Go(src, retain, true, out p, out len);
    /// ABI v1 section 9's move path (WP8): encode and leave the output IN the encode context,
    /// no ak_enc_take, for ak_call_unary_enc / ak_call_send_enc to move as the request body.
    public int EncodeInto(ListProbeResponse src, bool retain)
    {
        _keep = true;
        try { return Go(src, retain, true, out _, out _); }
        finally { _keep = false; }
    }
    /// A copy of the bytes an EncodeInto left in the context (ak_enc_take reads them without
    /// consuming them); for checks, never on a timed path.
    public byte[] ContextBytes()
    {
        byte* bp; nuint blen;
        int tk = Abi.ak_enc_take(_ctx, &bp, &blen);
        if (tk != 0) throw new InvalidOperationException($"core encode failed: {tk}");
        return new ReadOnlySpan<byte>(bp, (int)blen).ToArray();
    }
    /// The encode context, for the move path's entries.
    public IntPtr EncContext => _ctx;
    private bool _keep;
    public byte[] EncodeToArray(ListProbeResponse src, bool retain = false)
    {
        int rc = Go(src, retain, true, out byte* p, out int len);
        if (rc < 0) throw new InvalidOperationException($"core encode failed: {rc}");
        var a = new byte[len];
        new ReadOnlySpan<byte>(p, len).CopyTo(a);
        return a;
    }

    private int Go(ListProbeResponse src, bool retain, bool call, out byte* outPtr, out int outLen)
    {
        outPtr = null; outLen = 0;
        Abi.ak_enc_reset(_ctx);
        _st.Reset();
        int __d = Stage.Defer;   // E1R / E1C: read once; the default path tests this local only
        long __mk0 = 0, __pt0 = 0;
        if (__d != 0) { __mk0 = Stage.Marked; __pt0 = Stage.Patched; }   // this encode's marks and patches
        _run->Chunk = Chunk;
        if (retain) throw new NotSupportedException("unknown fields are compiled out of this build (WP5 step 10): no ak_uencode");
        {
            var lst = src.Probes;
            int n = lst == null ? 0 : lst.Count;
            _run->N_probes = n;
            Arr.Ensure(ref _run->S_probes, ref _cap_probes, n, sizeof(ak_efix_Probe));
            for (int i = 0; i < n; i++)
            {
                G.E_Probe(ref ((ak_efix_Probe*)_run->S_probes)[i], lst[i], _st);
            }
        }
        var vt = new ak_evt_ListProbeResponse
        {
            loop_probes = &Loop_probes,
        };
        nint rc;
        {
            var fix = new ak_efix_ListProbeResponse();
            G.E_ListProbeResponse(ref fix, src, _st);
            if (!call) return 0;
            _fwd++;
            if (__d != 0) { if (Stage.Marked == __mk0) __d = 0; else { _pinSrc = src; Stage.DeferNow = __d; } }
            rc = Abi.ak_encode_ListProbeResponse(_run, _ctx, &vt, &fix);
        }
        _st.ReleasePins();   // D21 E1: the core has copied every pinned string
        if (__d != 0)
        {
            Stage.DeferNow = 0;   // the next encode on this thread starts from the default
            _pinSrc = null;
            // E1R / E1C: every mark the fill left was patched by a frame before the core read it.
            if (Stage.Marked - __mk0 != Stage.Patched - __pt0 && rc >= 0) rc = Abi.AK_ERR_HOST;
        }
        if (rc < 0) return (int)rc;
        if (_keep) return 0;   // EncodeInto: the output stays in the context (the move path)
        byte* bp; nuint blen;
        int tk = Abi.ak_enc_take(_ctx, &bp, &blen);
        if (tk != 0) return tk;
        outPtr = bp; outLen = (int)blen;
        return 0;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct DecRun { public IntPtr Target; public byte* Buf; }

    private static ListProbeResponse Tgt(void* obj) => (ListProbeResponse)GCHandle.FromIntPtr(((DecRun*)obj)->Target).Target;

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void ApplyRoot(IntPtr ctx, void* obj, ak_dfix_ListProbeResponse* fix)
    {
        _rev++;
        try { if (G.PlantHostFail == 1) throw new InvalidOperationException("planted host failure (apply)"); G.D_ListProbeResponse(ref *fix, Tgt(obj), ((DecRun*)obj)->Buf); }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_probes(IntPtr ctx, void* obj, long token, ak_dfix_Probe* xs, int n)
    {
        _rev++;
        try
        {
            if (G.PlantHostFail == 2) throw new InvalidOperationException("planted host failure (add)");
            byte* b = ((DecRun*)obj)->Buf;
            var lst = Tgt(obj).Probes;
            lst.EnsureCapacity(lst.Count + n);   // step 9a: the run's count is known
            for (int i = 0; i < n; i++) { var x = new Probe(); G.D_Probe(ref xs[i], x, b); lst.Add(x); }
        }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    private static readonly byte[] One = new byte[1];

    /// WP5 step 10: this build has unknown fields COMPILED OUT (no options, no resets).
    public const bool UnknownCompiledOut = true;
    public const int UNDELIVERED = -1001;   // never returned by this build
    public int Undelivered => 0;
    public long ResetCalls => 0;

    private void EnsureDec()
    {
        if (_dctx != IntPtr.Zero) return;
        _dctx = Abi.ak_dec_ctx_new_ListProbeResponse();   // rule 6: bound to this root; no options exist
        if (_dctx == IntPtr.Zero) throw new InvalidOperationException("ak_dec_ctx_new_ListProbeResponse returned NULL");
        // D20: the pull family's bits, copied into this root-bound context (every bit: G.Str validates).
        int sp = Abi.ak_dec_set_pvt_ListProbeResponse(_dctx, Pvt);   // step 5b: the root's one native pvt
        if (sp != 0) throw new InvalidOperationException("ak_dec_set_pvt_ListProbeResponse: " + sp);
        // D23 / D24: the FSM's own D20 mask, copied once into the context when it is created (set
        // lazily on the first FSM decode, it made one count row depend on which thread decoded).
        int fp = Abi.ak_fsm_set_pvt_ListProbeResponse(_dctx, FsmPvt);
        if (fp != 0) throw new InvalidOperationException("ak_fsm_set_pvt_ListProbeResponse: " + fp);
        _drun = (DecRun*)NativeMemory.AllocZeroed((nuint)sizeof(DecRun));
    }

    private int ArmFor(int mode) => mode == -2 ? 0 : throw new NotSupportedException("unknown fields are compiled out of this build (WP5 step 10)");
    private int Disarm(int rc) => rc;

    public ListProbeResponse Decode(byte[] src, int len) { int rc = TryDecode(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core decode failed: {rc}"); return t; }

    /// The core's code (< 0) on failure; the output is then unspecified and discarded (R-G6).
    public int TryDecode(byte[] src, int len, bool retain, out ListProbeResponse result) => DecodeArmed(src, len, retain ? -1 : -2, out result);

    /// Step 5b (owner, 2026-10-04): the push vtable, built ONCE per root and kept in native
    /// memory (NativeMemory.Alloc, never freed: one per root for the process), so no decode
    /// writes it and the GC cannot move it. Not a static field of the struct type taken by
    /// address: a non-primitive struct static lives in a boxed object on the GC heap, which
    /// compaction may move, so its address is not stable without a pin. The core only reads
    /// the vtable during the call.
    private static readonly ak_dvt_ListProbeResponse* Vt = MakeVt();
    private static ak_dvt_ListProbeResponse* MakeVt()
    {
        var v = (ak_dvt_ListProbeResponse*)NativeMemory.AllocZeroed((nuint)sizeof(ak_dvt_ListProbeResponse));
        v->utf8_skip = AkUtf8Skip.ListProbeResponse_ALL;   // D20: every bit set, G.Str validates (strict)
        v->apply = &ApplyRoot;
        v->add_probes = &Add_probes;
        return v;
    }
    /// Step 5b: the pull family's bits, once per root in native memory (the setter copies them).
    private static readonly ak_pvt_ListProbeResponse* Pvt = MakePvt();
    private static ak_pvt_ListProbeResponse* MakePvt() { var v = (ak_pvt_ListProbeResponse*)NativeMemory.AllocZeroed((nuint)sizeof(ak_pvt_ListProbeResponse)); v->utf8_skip = AkUtf8Skip.ListProbeResponse_ALL; return v; }
    private GCHandle _th;
    private int DecodeArmed(byte[] src, int len, int mode, out ListProbeResponse result)
    {
        result = null;
        EnsureDec();
        // Step a2 (i): no ak_dec_err_reset / ak_dec_err: ak_decode_* clears the context's
        // sticky slot on entry and returns it (a host failure reported through ak_fail
        // from a reverse call included), so its return value carries every error.
        int ar = ArmFor(mode);
        if (ar != 0) { Disarm(ar); return ar; }
        var target = new ListProbeResponse();
        // Step a2 (ii): one GCHandle per instance, its Target set for this decode.
        if (!_th.IsAllocated) _th = GCHandle.Alloc(null);
        _th.Target = target;
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                // (NULL, 0) is never handed to the core: an empty buffer is a valid pointer and 0.
                byte* b = len == 0 ? one : b0;
                _drun->Target = GCHandle.ToIntPtr(_th);
                _drun->Buf = b;
                _fwd++;
                rc = Abi.ak_decode_ListProbeResponse(_dctx, _drun, b, (nuint)len, Vt);
            }
        }
        finally { _th.Target = null; rc = Disarm(rc); }
        if (rc < 0) return rc;
        result = target;
        return 0;
    }

    /// D21 s8 attribution (HARNESS ONLY): the same push decode through another vtable.
    /// kind 0 `parse`: every callback null but `new_<slot>` (NewZero: the core skips a non-leaf
    /// element whose `new_` is null), utf8_skip all bits (as the reference); kind 1 `noop`:
    /// every callback G.Noop (new_: NewZero); kind 2 `parse-validate`: kind 0 with utf8_skip 0
    /// (the core validates every string).
    public static readonly ak_dvt_ListProbeResponse* VtParse = MakeVtAttr(0), VtNoop = MakeVtAttr(1), VtParseValidate = MakeVtAttr(2);
    private static ak_dvt_ListProbeResponse* MakeVtAttr(int kind)
    {
        var v = (ak_dvt_ListProbeResponse*)NativeMemory.AllocZeroed((nuint)sizeof(ak_dvt_ListProbeResponse));
        v->utf8_skip = kind == 2 ? 0 : AkUtf8Skip.ListProbeResponse_ALL;
        if (kind == 1) *(void**)&v->apply = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_probes = G.NoopPtr;
        return v;
    }
    /// D21 s8 attribution (HARNESS ONLY): DecodeArmed through `vt`; the graph is the bare
    /// root (the callbacks build nothing) and buffers the callbacks did not take are not
    /// UNDELIVERED here (the arena rewinds at the next decode).
    public int DecodeVt(byte[] src, int len, bool retain, ak_dvt_ListProbeResponse* vt)
    {
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        if (!_th.IsAllocated) _th = GCHandle.Alloc(null);
        int rc;
        fixed (byte* b0 = src)
        fixed (byte* one = One)
        {
            byte* b = len == 0 ? one : b0;
            _drun->Target = GCHandle.ToIntPtr(_th);
            _drun->Buf = b;
            rc = Abi.ak_decode_ListProbeResponse(_dctx, _drun, b, (nuint)len, vt);
        }
        rc = Disarm(rc);
        return rc == UNDELIVERED ? 0 : rc;
    }
    /// D21 s8 attribution (HARNESS ONLY): the pull family's parse alone (no replay).
    public int ParseOnly(byte[] src, int len, bool retain)
    {
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        int rc;
        fixed (byte* b0 = src)
        fixed (byte* one = One)
            rc = Abi.ak_parse_ListProbeResponse(_dctx, len == 0 ? one : b0, (nuint)len);
        rc = Disarm(rc);
        return rc == UNDELIVERED ? 0 : rc;
    }

    /// ABI v1 7.1's PULL family: parse into the context's record stream (no reverse
    /// call but grow), then replay it with the same group readers the push callbacks
    /// use. The context is armed exactly as for push.
    public ListProbeResponse Pull(byte[] src, int len) { int rc = TryPull(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core parse failed: {rc}"); return t; }

    public int TryPull(byte[] src, int len, bool retain, out ListProbeResponse result)
    {
        result = null;
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        var t = new ListProbeResponse();
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                byte* b = len == 0 ? one : b0;
                _fwd++;
                rc = Abi.ak_parse_ListProbeResponse(_dctx, b, (nuint)len);
                if (rc >= 0)
                {
                    byte* recs; nuint rlen;
                    _fwd++;
                    rc = Abi.ak_bdr_ptr(_dctx, &recs, &rlen);
                    if (rc == 0) { try { Replay(t, b, recs, (int)rlen); } catch (DecoderFallbackException) { rc = Abi.AK_ERR_TRANSCODE; } }
                }
            }
        }
        finally { rc = Disarm(rc); }
        if (rc < 0) return rc;
        result = t;
        return 0;
    }

    private const uint OP_APPLY = 1, OP_ADD = 2, OP_NEW = 3, OP_APPLY_ELEM = 4;   // ak_bdr_rec.op
    private static void Replay(ListProbeResponse t, byte* b, byte* p, int len)
    {
        int at = 0;
        while (len - at >= sizeof(ak_bdr_rec))
        {
            ref var r = ref *(ak_bdr_rec*)(p + at);
            byte* body = p + at + sizeof(ak_bdr_rec);
            at += sizeof(ak_bdr_rec) + (int)r.bytes;
            uint outer = r.slot >> 16, inner = r.slot & 0xFFFF;
            switch (r.op)
            {
                case OP_APPLY: G.D_ListProbeResponse(ref *(ak_dfix_ListProbeResponse*)body, t, b); break;
                case OP_ADD when outer == 0 && inner == 1:   // a root-level run
                {
                    var xs = (ak_dfix_Probe*)body; var lst = t.Probes;
                    lst.EnsureCapacity(lst.Count + (int)r.n);   // step 9a: the run's count is known
                    for (int i = 0; i < (int)r.n; i++) { var x = new Probe(); G.D_Probe(ref xs[i], x, b); lst.Add(x); }
                    break;
                }
                default: break;
            }
        }
    }

    /// FIX-PLAN D23: the FSM decode family. ak_fsm_begin_ListProbeResponse returns the
    /// first event, ak_fsm_next_ListProbeResponse each next one, each RETURNING the
    /// event's op (> 0; the root APPLY is the last, the end) or an error (< 0); every
    /// event is consumed (FsmDispatch) before the next call, which may overwrite its
    /// payload. One `fixed` spans begin and every next (the core holds spans into the
    /// input until the end event). Arming, Disarm, retain ownership and the failure
    /// path are pull's; a failed decode's partial object is discarded.
    public ListProbeResponse Fsm(byte[] src, int len) { int rc = TryFsm(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core FSM decode failed: {rc}"); return t; }
    /// D23: the FSM's own D20 mask (every bit: G.Str validates), native, copied by its setter
    /// (ak_fsm_set_pvt_<Root>) once, when EnsureDec creates the context.
    private static readonly ak_pvt_ListProbeResponse* FsmPvt = MakeFsmPvt();
    private static ak_pvt_ListProbeResponse* MakeFsmPvt() { var v = (ak_pvt_ListProbeResponse*)NativeMemory.AllocZeroed((nuint)sizeof(ak_pvt_ListProbeResponse)); v->utf8_skip = AkUtf8Skip.ListProbeResponse_ALL; return v; }

    public int TryFsm(byte[] src, int len, bool retain, out ListProbeResponse result)
    {
        result = null;
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        var t = new ListProbeResponse();
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                byte* b = len == 0 ? one : b0;
                ak_fsm_ev ev;
                _fwd++;
                int op = Abi.ak_fsm_begin_ListProbeResponse(_dctx, b, (nuint)len, &ev);
                try
                {
                    while (op > 0)
                    {
                        if (op == (int)Abi.AK_BDR_APPLY)
                        {
                            // The root group: always the last event, the end.
                            G.D_ListProbeResponse(ref *(ak_dfix_ListProbeResponse*)ev.data, t, b);
                            break;
                        }
                        FsmDispatch(t, b, (uint)op, &ev);
                        _fwd++;
                        op = Abi.ak_fsm_next_ListProbeResponse(_dctx, &ev);
                    }
                    rc = op < 0 ? op : 0;
                }
                catch (DecoderFallbackException) { rc = Abi.AK_ERR_TRANSCODE; }
            }
        }
        finally { rc = Disarm(rc); }
        if (rc < 0) return rc;   // the partial object is dropped
        result = t;
        return 0;
    }

    /// D23: one non-final event, `op` the call's return (NEW, ADD, APPLY_ELEM; the root APPLY is the end event,
    /// handled by TryFsm). slot = outer << 16 | inner, pull's numbering: a root-level run
    /// is (0, slot), a non-leaf slot's element is (slot, 0) and its inner runs (slot, inner).
    private static void FsmDispatch(ListProbeResponse t, byte* b, uint op, ak_fsm_ev* ev)
    {
        byte* d = (byte*)ev->data;
        switch (op)
        {
            case Abi.AK_BDR_ADD:
                switch (ev->slot)
                {
                    case 1u:   // a root-level run
                    {
                        var xs = (ak_dfix_Probe*)d; var lst = t.Probes; int n = (int)ev->n;
                        lst.EnsureCapacity(lst.Count + n);
                        for (int i = 0; i < n; i++) { var x = new Probe(); G.D_Probe(ref xs[i], x, b); lst.Add(x); }
                        return;
                    }
                }
                return;
        }
    }

    public long PullFootprint() => _dctx == IntPtr.Zero ? 0 : (long)Abi.ak_bdr_footprint(_dctx);
    public AkCounters EncCounters() { AkCounters c; Abi.ak_enc_counters(_ctx, &c); return c; }
    public void EncCountersReset() => Abi.ak_enc_counters_reset(_ctx);
    public AkCounters DecCounters() { AkCounters c; if (_dctx == IntPtr.Zero) return default; Abi.ak_dec_counters(_dctx, &c); return c; }
    public void DecCountersReset() { if (_dctx != IntPtr.Zero) Abi.ak_dec_counters_reset(_dctx); }

    public void Dispose()
    {
        if (_ctx != IntPtr.Zero) { Abi.ak_enc_ctx_free(_ctx); _ctx = IntPtr.Zero; }
        if (_dctx != IntPtr.Zero) { Abi.ak_dec_ctx_free(_dctx); _dctx = IntPtr.Zero; }
        if (_th.IsAllocated) _th.Free();
        _st.Dispose();
        if (_run != null)
        {
            NativeMemory.Free(_run->S_probes);
            NativeMemory.Free(_run); _run = null;
        }
        if (_drun != null) { NativeMemory.Free(_drun); _drun = null; }
    }
}

