    public void* I_batches_values; public int* O_batches_values; public int* C_batches_values;
    public void* I_batches_codes; public int* O_batches_codes; public int* C_batches_codes;
    public void* I_batches_flags; public int* O_batches_flags; public int* C_batches_flags;
