    private int _cap_batches;
    private int _cap_batches_ticks, _capo_batches_ticks;
    private int _cap_batches_values, _capo_batches_values;
    private int _cap_batches_codes, _capo_batches_codes;
    private int _cap_batches_flags, _capo_batches_flags;
    private int _cap_batches_statuses, _capo_batches_statuses;
