        }
        var vt = new ak_evt_DualResponse
        {
            loop_left = &Loop_left,
            loop_right = &Loop_right,
        };
        nint rc;
        {
            var fix = new ak_efix_DualResponse();
            G.E_DualResponse(ref fix, src, _st);
            if (!call) return 0;
            _fwd++;
            if (__d != 0) { if (Stage.Marked == __mk0) __d = 0; else { _pinSrc = src; Stage.DeferNow = __d; } }
            rc = Abi.ak_encode_DualResponse(_run, _ctx, &vt, &fix);
        }
        _st.ReleasePins();   // D21 E1: the core has copied every pinned string
        if (__d != 0)
        {
            Stage.DeferNow = 0;   // the next encode on this thread starts from the default
            _pinSrc = null;
            // E1R / E1C: every mark the fill left was patched by a frame before the core read it.
            if (Stage.Marked - __mk0 != Stage.Patched - __pt0 && rc >= 0) rc = Abi.AK_ERR_HOST;
        }
        if (rc < 0) return (int)rc;
        if (_keep) return 0;   // EncodeInto: the output stays in the context (the move path)
        byte* bp; nuint blen;
        int tk = Abi.ak_enc_take(_ctx, &bp, &blen);
        if (tk != 0) return tk;
        outPtr = bp; outLen = (int)blen;
        return 0;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct DecRun { public IntPtr Target; public byte* Buf; }

    private static DualResponse Tgt(void* obj) => (DualResponse)GCHandle.FromIntPtr(((DecRun*)obj)->Target).Target;

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void ApplyRoot(IntPtr ctx, void* obj, ak_dfix_DualResponse* fix)
    {
        _rev++;
        try { if (G.PlantHostFail == 1) throw new InvalidOperationException("planted host failure (apply)"); G.D_DualResponse(ref *fix, Tgt(obj), ((DecRun*)obj)->Buf); }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_left(IntPtr ctx, void* obj, long token, ak_dfix_Pair* xs, int n)
    {
        _rev++;
        try
        {
            if (G.PlantHostFail == 2) throw new InvalidOperationException("planted host failure (add)");
            byte* b = ((DecRun*)obj)->Buf;
            var lst = Tgt(obj).Left;
            lst.EnsureCapacity(lst.Count + n);   // step 9a: the run's count is known
            for (int i = 0; i < n; i++) { var x = new Pair(); G.D_Pair(ref xs[i], x, b); lst.Add(x); }
        }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_right(IntPtr ctx, void* obj, long token, ak_dfix_Pair* xs, int n)
    {
        _rev++;
        try
        {
            if (G.PlantHostFail == 2) throw new InvalidOperationException("planted host failure (add)");
            byte* b = ((DecRun*)obj)->Buf;
            var lst = Tgt(obj).Right;
            lst.EnsureCapacity(lst.Count + n);   // step 9a: the run's count is known
            for (int i = 0; i < n; i++) { var x = new Pair(); G.D_Pair(ref xs[i], x, b); lst.Add(x); }
        }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    private static readonly byte[] One = new byte[1];

    /// WP5 step 10: this build has unknown fields COMPILED OUT (no options, no resets).
    public const bool UnknownCompiledOut = true;
    public const int UNDELIVERED = -1001;   // never returned by this build
    public int Undelivered => 0;
    public long ResetCalls => 0;

    private void EnsureDec()
    {
        if (_dctx != IntPtr.Zero) return;
        _dctx = Abi.ak_dec_ctx_new_DualResponse();   // rule 6: bound to this root; no options exist
        if (_dctx == IntPtr.Zero) throw new InvalidOperationException("ak_dec_ctx_new_DualResponse returned NULL");
        // D20: the pull family's bits, copied into this root-bound context (every bit: G.Str validates).
        int sp = Abi.ak_dec_set_pvt_DualResponse(_dctx, Pvt);   // step 5b: the root's one native pvt
        if (sp != 0) throw new InvalidOperationException("ak_dec_set_pvt_DualResponse: " + sp);
        // D23 / D24: the FSM's own D20 mask, copied once into the context when it is created (set
        // lazily on the first FSM decode, it made one count row depend on which thread decoded).
        int fp = Abi.ak_fsm_set_pvt_DualResponse(_dctx, FsmPvt);
        if (fp != 0) throw new InvalidOperationException("ak_fsm_set_pvt_DualResponse: " + fp);
        _drun = (DecRun*)NativeMemory.AllocZeroed((nuint)sizeof(DecRun));
    }

    private int ArmFor(int mode) => mode == -2 ? 0 : throw new NotSupportedException("unknown fields are compiled out of this build (WP5 step 10)");
    private int Disarm(int rc) => rc;

    public DualResponse Decode(byte[] src, int len) { int rc = TryDecode(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core decode failed: {rc}"); return t; }

    /// The core's code (< 0) on failure; the output is then unspecified and discarded (R-G6).
    public int TryDecode(byte[] src, int len, bool retain, out DualResponse result) => DecodeArmed(src, len, retain ? -1 : -2, out result);

    /// Step 5b (owner, 2026-10-04): the push vtable, built ONCE per root and kept in native
    /// memory (NativeMemory.Alloc, never freed: one per root for the process), so no decode
    /// writes it and the GC cannot move it. Not a static field of the struct type taken by
    /// address: a non-primitive struct static lives in a boxed object on the GC heap, which
    /// compaction may move, so its address is not stable without a pin. The core only reads
    /// the vtable during the call.
    private static readonly ak_dvt_DualResponse* Vt = MakeVt();
    private static ak_dvt_DualResponse* MakeVt()
    {
        var v = (ak_dvt_DualResponse*)NativeMemory.AllocZeroed((nuint)sizeof(ak_dvt_DualResponse));
        v->utf8_skip = AkUtf8Skip.DualResponse_ALL;   // D20: every bit set, G.Str validates (strict)
        v->apply = &ApplyRoot;
        v->add_left = &Add_left;
        v->add_right = &Add_right;
        return v;
    }
    /// Step 5b: the pull family's bits, once per root in native memory (the setter copies them).
    private static readonly ak_pvt_DualResponse* Pvt = MakePvt();
    private static ak_pvt_DualResponse* MakePvt() { var v = (ak_pvt_DualResponse*)NativeMemory.AllocZeroed((nuint)sizeof(ak_pvt_DualResponse)); v->utf8_skip = AkUtf8Skip.DualResponse_ALL; return v; }
    private GCHandle _th;
    private int DecodeArmed(byte[] src, int len, int mode, out DualResponse result)
    {
        result = null;
        EnsureDec();
        // Step a2 (i): no ak_dec_err_reset / ak_dec_err: ak_decode_* clears the context's
        // sticky slot on entry and returns it (a host failure reported through ak_fail
        // from a reverse call included), so its return value carries every error.
        int ar = ArmFor(mode);
        if (ar != 0) { Disarm(ar); return ar; }
        var target = new DualResponse();
        // Step a2 (ii): one GCHandle per instance, its Target set for this decode.
        if (!_th.IsAllocated) _th = GCHandle.Alloc(null);
        _th.Target = target;
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                // (NULL, 0) is never handed to the core: an empty buffer is a valid pointer and 0.
                byte* b = len == 0 ? one : b0;
                _drun->Target = GCHandle.ToIntPtr(_th);
                _drun->Buf = b;
                _fwd++;
                rc = Abi.ak_decode_DualResponse(_dctx, _drun, b, (nuint)len, Vt);
            }
        }
        finally { _th.Target = null; rc = Disarm(rc); }
        if (rc < 0) return rc;
        result = target;
        return 0;
    }

    /// D21 s8 attribution (HARNESS ONLY): the same push decode through another vtable.
    /// kind 0 `parse`: every callback null but `new_<slot>` (NewZero: the core skips a non-leaf
    /// element whose `new_` is null), utf8_skip all bits (as the reference); kind 1 `noop`:
    /// every callback G.Noop (new_: NewZero); kind 2 `parse-validate`: kind 0 with utf8_skip 0
    /// (the core validates every string).
    public static readonly ak_dvt_DualResponse* VtParse = MakeVtAttr(0), VtNoop = MakeVtAttr(1), VtParseValidate = MakeVtAttr(2);
    private static ak_dvt_DualResponse* MakeVtAttr(int kind)
    {
        var v = (ak_dvt_DualResponse*)NativeMemory.AllocZeroed((nuint)sizeof(ak_dvt_DualResponse));
        v->utf8_skip = kind == 2 ? 0 : AkUtf8Skip.DualResponse_ALL;
        if (kind == 1) *(void**)&v->apply = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_left = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_right = G.NoopPtr;
        return v;
    }
    /// D21 s8 attribution (HARNESS ONLY): DecodeArmed through `vt`; the graph is the bare
    /// root (the callbacks build nothing) and buffers the callbacks did not take are not
    /// UNDELIVERED here (the arena rewinds at the next decode).
    public int DecodeVt(byte[] src, int len, bool retain, ak_dvt_DualResponse* vt)
    {
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        if (!_th.IsAllocated) _th = GCHandle.Alloc(null);
        int rc;
        fixed (byte* b0 = src)
        fixed (byte* one = One)
        {
            byte* b = len == 0 ? one : b0;
            _drun->Target = GCHandle.ToIntPtr(_th);
            _drun->Buf = b;
            rc = Abi.ak_decode_DualResponse(_dctx, _drun, b, (nuint)len, vt);
        }
        rc = Disarm(rc);
        return rc == UNDELIVERED ? 0 : rc;
    }
    /// D21 s8 attribution (HARNESS ONLY): the pull family's parse alone (no replay).
    public int ParseOnly(byte[] src, int len, bool retain)
    {
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        int rc;
        fixed (byte* b0 = src)
        fixed (byte* one = One)
            rc = Abi.ak_parse_DualResponse(_dctx, len == 0 ? one : b0, (nuint)len);
        rc = Disarm(rc);
        return rc == UNDELIVERED ? 0 : rc;
    }

    /// ABI v1 7.1's PULL family: parse into the context's record stream (no reverse
    /// call but grow), then replay it with the same group readers the push callbacks
    /// use. The context is armed exactly as for push.
    public DualResponse Pull(byte[] src, int len) { int rc = TryPull(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core parse failed: {rc}"); return t; }

    public int TryPull(byte[] src, int len, bool retain, out DualResponse result)
    {
        result = null;
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        var t = new DualResponse();
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                byte* b = len == 0 ? one : b0;
                _fwd++;
                rc = Abi.ak_parse_DualResponse(_dctx, b, (nuint)len);
                if (rc >= 0)
                {
                    byte* recs; nuint rlen;
                    _fwd++;
                    rc = Abi.ak_bdr_ptr(_dctx, &recs, &rlen);
                    if (rc == 0) { try { Replay(t, b, recs, (int)rlen); } catch (DecoderFallbackException) { rc = Abi.AK_ERR_TRANSCODE; } }
                }
            }
        }
        finally { rc = Disarm(rc); }
        if (rc < 0) return rc;
        result = t;
        return 0;
    }

    private const uint OP_APPLY = 1, OP_ADD = 2, OP_NEW = 3, OP_APPLY_ELEM = 4;   // ak_bdr_rec.op
    private static void Replay(DualResponse t, byte* b, byte* p, int len)
    {
        int at = 0;
        while (len - at >= sizeof(ak_bdr_rec))
        {
            ref var r = ref *(ak_bdr_rec*)(p + at);
            byte* body = p + at + sizeof(ak_bdr_rec);
            at += sizeof(ak_bdr_rec) + (int)r.bytes;
            uint outer = r.slot >> 16, inner = r.slot & 0xFFFF;
            switch (r.op)
            {
                case OP_APPLY: G.D_DualResponse(ref *(ak_dfix_DualResponse*)body, t, b); break;
                case OP_ADD when outer == 0 && inner == 1:   // a root-level run
                {
                    var xs = (ak_dfix_Pair*)body; var lst = t.Left;
                    lst.EnsureCapacity(lst.Count + (int)r.n);   // step 9a: the run's count is known
                    for (int i = 0; i < (int)r.n; i++) { var x = new Pair(); G.D_Pair(ref xs[i], x, b); lst.Add(x); }
                    break;
                }
                case OP_ADD when outer == 0 && inner == 2:   // a root-level run
                {
                    var xs = (ak_dfix_Pair*)body; var lst = t.Right;
                    lst.EnsureCapacity(lst.Count + (int)r.n);   // step 9a: the run's count is known
                    for (int i = 0; i < (int)r.n; i++) { var x = new Pair(); G.D_Pair(ref xs[i], x, b); lst.Add(x); }
                    break;
                }
                default: break;
            }
        }
    }

    /// FIX-PLAN D23: the FSM decode family. ak_fsm_begin_DualResponse returns the first
    /// event, ak_fsm_next_DualResponse each next one, each RETURNING the event's op (>
    /// 0; the root APPLY is the last, the end) or an error (< 0); every event is
    /// consumed (FsmDispatch) before the next call, which may overwrite its payload.
    /// One `fixed` spans begin and every next (the core holds spans into the input
    /// until the end event). Arming, Disarm, retain ownership and the failure path are
    /// pull's; a failed decode's partial object is discarded.
    public DualResponse Fsm(byte[] src, int len) { int rc = TryFsm(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core FSM decode failed: {rc}"); return t; }
    /// D23: the FSM's own D20 mask (every bit: G.Str validates), native, copied by its setter
    /// (ak_fsm_set_pvt_<Root>) once, when EnsureDec creates the context.
    private static readonly ak_pvt_DualResponse* FsmPvt = MakeFsmPvt();
    private static ak_pvt_DualResponse* MakeFsmPvt() { var v = (ak_pvt_DualResponse*)NativeMemory.AllocZeroed((nuint)sizeof(ak_pvt_DualResponse)); v->utf8_skip = AkUtf8Skip.DualResponse_ALL; return v; }

    public int TryFsm(byte[] src, int len, bool retain, out DualResponse result)
    {
        result = null;
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        var t = new DualResponse();
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                byte* b = len == 0 ? one : b0;
                ak_fsm_ev ev;
                _fwd++;
                int op = Abi.ak_fsm_begin_DualResponse(_dctx, b, (nuint)len, &ev);
                try
                {
                    while (op > 0)
                    {
                        if (op == (int)Abi.AK_BDR_APPLY)
                        {
                            // The root group: always the last event, the end.
                            G.D_DualResponse(ref *(ak_dfix_DualResponse*)ev.data, t, b);
                            break;
                        }
                        FsmDispatch(t, b, (uint)op, &ev);
                        _fwd++;
                        op = Abi.ak_fsm_next_DualResponse(_dctx, &ev);
                    }
                    rc = op < 0 ? op : 0;
                }
                catch (DecoderFallbackException) { rc = Abi.AK_ERR_TRANSCODE; }
            }
        }
        finally { rc = Disarm(rc); }
        if (rc < 0) return rc;   // the partial object is dropped
        result = t;
        return 0;
    }

    /// D23: one non-final event, `op` the call's return (NEW, ADD, APPLY_ELEM; the root APPLY is the end event,
    /// handled by TryFsm). slot = outer << 16 | inner, pull's numbering: a root-level run
    /// is (0, slot), a non-leaf slot's element is (slot, 0) and its inner runs (slot, inner).
    private static void FsmDispatch(DualResponse t, byte* b, uint op, ak_fsm_ev* ev)
    {
        byte* d = (byte*)ev->data;
        switch (op)
        {
            case Abi.AK_BDR_ADD:
                switch (ev->slot)
                {
                    case 1u:   // a root-level run
                    {
                        var xs = (ak_dfix_Pair*)d; var lst = t.Left; int n = (int)ev->n;
                        lst.EnsureCapacity(lst.Count + n);
                        for (int i = 0; i < n; i++) { var x = new Pair(); G.D_Pair(ref xs[i], x, b); lst.Add(x); }
                        return;
                    }
                    case 2u:   // a root-level run
                    {
                        var xs = (ak_dfix_Pair*)d; var lst = t.Right; int n = (int)ev->n;
                        lst.EnsureCapacity(lst.Count + n);
                        for (int i = 0; i < n; i++) { var x = new Pair(); G.D_Pair(ref xs[i], x, b); lst.Add(x); }
                        return;
                    }
                }
                return;
        }
    }

    public long PullFootprint() => _dctx == IntPtr.Zero ? 0 : (long)Abi.ak_bdr_footprint(_dctx);
    public AkCounters EncCounters() { AkCounters c; Abi.ak_enc_counters(_ctx, &c); return c; }
    public void EncCountersReset() => Abi.ak_enc_counters_reset(_ctx);
    public AkCounters DecCounters() { AkCounters c; if (_dctx == IntPtr.Zero) return default; Abi.ak_dec_counters(_dctx, &c); return c; }
    public void DecCountersReset() { if (_dctx != IntPtr.Zero) Abi.ak_dec_counters_reset(_dctx); }

    public void Dispose()
    {
        if (_ctx != IntPtr.Zero) { Abi.ak_enc_ctx_free(_ctx); _ctx = IntPtr.Zero; }
        if (_dctx != IntPtr.Zero) { Abi.ak_dec_ctx_free(_dctx); _dctx = IntPtr.Zero; }
        if (_th.IsAllocated) _th.Free();
        _st.Dispose();
        if (_run != null)
        {
            NativeMemory.Free(_run->S_left);
            NativeMemory.Free(_run->S_right);
            NativeMemory.Free(_run); _run = null;
        }
        if (_drun != null) { NativeMemory.Free(_drun); _drun = null; }
    }
}

[StructLayout(LayoutKind.Sequential)]
public unsafe struct Run_ChunkLeaf
{
    public int Chunk;
    public int Retain;
}

/// core-ffi for `ChunkLeaf`: every group, slot and entry point from the plan.
public sealed unsafe class CoreFfi_ChunkLeaf : IDisposable
{
    private IntPtr _ctx, _dctx;
    private readonly Stage _st;
    private Run_ChunkLeaf* _run;
    private DecRun* _drun;
    public int Chunk;
    /// Counted where each crossing happens (R5). Static: an [UnmanagedCallersOnly]
    /// callback cannot reach an instance; one arm at a time.
    private static long _fwd, _rev;
    public long ForwardCalls => _fwd;
    public long ReverseCalls => _rev;
    public void CallsReset() { _fwd = 0; _rev = 0; }

    public CoreFfi_ChunkLeaf(bool utf16 = false)
    {
        _ctx = Abi.ak_enc_ctx_new();
        if (_ctx == IntPtr.Zero) throw new InvalidOperationException("ak_enc_ctx_new returned null");
        _st = new Stage(utf16 || Environment.GetEnvironmentVariable("AK_UTF16") == "1");
        _run = (Run_ChunkLeaf*)NativeMemory.AllocZeroed((nuint)sizeof(Run_ChunkLeaf));
    }

    /// E1R / E1C (D21 step 7): the facade root of the encode running on this thread, for the
    /// frames inside the loop callbacks to pin its strings.
    [ThreadStatic] private static ChunkLeaf _pinSrc;

    public int Fill(ChunkLeaf src) { Go(src, false, false, out _, out _); return 0; }
    public void Encode(ChunkLeaf src, out byte* p, out int len) { int rc = Go(src, false, true, out p, out len); if (rc < 0) throw new InvalidOperationException($"core encode failed: {rc}"); }
    public int TryEncode(ChunkLeaf src, bool retain, out byte* p, out int len) => Go(src, retain, true, out p, out len);
    /// ABI v1 section 9's move path (WP8): encode and leave the output IN the encode context,
    /// no ak_enc_take, for ak_call_unary_enc / ak_call_send_enc to move as the request body.
    public int EncodeInto(ChunkLeaf src, bool retain)
    {
        _keep = true;
        try { return Go(src, retain, true, out _, out _); }
        finally { _keep = false; }
    }
    /// A copy of the bytes an EncodeInto left in the context (ak_enc_take reads them without
    /// consuming them); for checks, never on a timed path.
    public byte[] ContextBytes()
    {
        byte* bp; nuint blen;
        int tk = Abi.ak_enc_take(_ctx, &bp, &blen);
        if (tk != 0) throw new InvalidOperationException($"core encode failed: {tk}");
        return new ReadOnlySpan<byte>(bp, (int)blen).ToArray();
    }
    /// The encode context, for the move path's entries.
    public IntPtr EncContext => _ctx;
    private bool _keep;
    public byte[] EncodeToArray(ChunkLeaf src, bool retain = false)
    {
        int rc = Go(src, retain, true, out byte* p, out int len);
        if (rc < 0) throw new InvalidOperationException($"core encode failed: {rc}");
        var a = new byte[len];
        new ReadOnlySpan<byte>(p, len).CopyTo(a);
        return a;
    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    private static nint RootPinR_e(Run_ChunkLeaf* _run, IntPtr _ctx, ak_evt_ChunkLeaf* vt, ak_efix_ChunkLeaf* __g, ChunkLeaf src)
    {
        fixed (char* __p0 = src.K)
        {
            if (__g->k.data == Stage.PinPending) { __g->k.data = (IntPtr)__p0; Stage.Patched++; }
            return Abi.ak_encode_ChunkLeaf(_run, _ctx, vt, __g);
        }
    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    private static nint RootPinH_e(Run_ChunkLeaf* _run, IntPtr _ctx, ak_evt_ChunkLeaf* vt, ak_efix_ChunkLeaf* __g, ChunkLeaf src)
    {
        int __h = Stage.ChunkMark();   // this chunk releases only the handles it adds
        if (__g->k.data == Stage.PinPending) { __g->k.data = Stage.PinChunk(src.K); }
        nint rc;
        rc = Abi.ak_encode_ChunkLeaf(_run, _ctx, vt, __g);
        Stage.ReleaseChunk(__h);
        return rc;
    }

    private int Go(ChunkLeaf src, bool retain, bool call, out byte* outPtr, out int outLen)
    {
        outPtr = null; outLen = 0;
        Abi.ak_enc_reset(_ctx);
        _st.Reset();
        int __d = Stage.Defer;   // E1R / E1C: read once; the default path tests this local only
        long __mk0 = 0, __pt0 = 0;
        if (__d != 0) { __mk0 = Stage.Marked; __pt0 = Stage.Patched; }   // this encode's marks and patches
        _run->Chunk = Chunk;
        if (retain) throw new NotSupportedException("unknown fields are compiled out of this build (WP5 step 10): no ak_uencode");
        var vt = new ak_evt_ChunkLeaf
        {
            _reserved = IntPtr.Zero,
        };
        nint rc;
        {
            var fix = new ak_efix_ChunkLeaf();
            G.E_ChunkLeaf(ref fix, src, _st);
            if (!call) return 0;
            _fwd++;
            if (__d != 0) { if (Stage.Marked == __mk0) __d = 0; else { _pinSrc = src; Stage.DeferNow = __d; } }
            if (__d == 0) rc = Abi.ak_encode_ChunkLeaf(_run, _ctx, &vt, &fix);
            else rc = __d == 1 ? RootPinR_e(_run, _ctx, &vt, &fix, src) : RootPinH_e(_run, _ctx, &vt, &fix, src);
        }
        _st.ReleasePins();   // D21 E1: the core has copied every pinned string
        if (__d != 0)
        {
            Stage.DeferNow = 0;   // the next encode on this thread starts from the default
            _pinSrc = null;
            // E1R / E1C: every mark the fill left was patched by a frame before the core read it.
            if (Stage.Marked - __mk0 != Stage.Patched - __pt0 && rc >= 0) rc = Abi.AK_ERR_HOST;
        }
        if (rc < 0) return (int)rc;
        if (_keep) return 0;   // EncodeInto: the output stays in the context (the move path)
        byte* bp; nuint blen;
        int tk = Abi.ak_enc_take(_ctx, &bp, &blen);
        if (tk != 0) return tk;
        outPtr = bp; outLen = (int)blen;
        return 0;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct DecRun { public IntPtr Target; public byte* Buf; }

    private static ChunkLeaf Tgt(void* obj) => (ChunkLeaf)GCHandle.FromIntPtr(((DecRun*)obj)->Target).Target;

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void ApplyRoot(IntPtr ctx, void* obj, ak_dfix_ChunkLeaf* fix)
    {
        _rev++;
        try { if (G.PlantHostFail == 1) throw new InvalidOperationException("planted host failure (apply)"); G.D_ChunkLeaf(ref *fix, Tgt(obj), ((DecRun*)obj)->Buf); }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    private static readonly byte[] One = new byte[1];

    /// WP5 step 10: this build has unknown fields COMPILED OUT (no options, no resets).
    public const bool UnknownCompiledOut = true;
    public const int UNDELIVERED = -1001;   // never returned by this build
    public int Undelivered => 0;
    public long ResetCalls => 0;

    private void EnsureDec()
    {
        if (_dctx != IntPtr.Zero) return;
        _dctx = Abi.ak_dec_ctx_new_ChunkLeaf();   // rule 6: bound to this root; no options exist
        if (_dctx == IntPtr.Zero) throw new InvalidOperationException("ak_dec_ctx_new_ChunkLeaf returned NULL");
        // D20: the pull family's bits, copied into this root-bound context (every bit: G.Str validates).
        int sp = Abi.ak_dec_set_pvt_ChunkLeaf(_dctx, Pvt);   // step 5b: the root's one native pvt
        if (sp != 0) throw new InvalidOperationException("ak_dec_set_pvt_ChunkLeaf: " + sp);
        // D23 / D24: the FSM's own D20 mask, copied once into the context when it is created (set
        // lazily on the first FSM decode, it made one count row depend on which thread decoded).
        int fp = Abi.ak_fsm_set_pvt_ChunkLeaf(_dctx, FsmPvt);
        if (fp != 0) throw new InvalidOperationException("ak_fsm_set_pvt_ChunkLeaf: " + fp);
        _drun = (DecRun*)NativeMemory.AllocZeroed((nuint)sizeof(DecRun));
    }

    private int ArmFor(int mode) => mode == -2 ? 0 : throw new NotSupportedException("unknown fields are compiled out of this build (WP5 step 10)");
    private int Disarm(int rc) => rc;

    public ChunkLeaf Decode(byte[] src, int len) { int rc = TryDecode(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core decode failed: {rc}"); return t; }

    /// The core's code (< 0) on failure; the output is then unspecified and discarded (R-G6).
    public int TryDecode(byte[] src, int len, bool retain, out ChunkLeaf result) => DecodeArmed(src, len, retain ? -1 : -2, out result);

    /// Step 5b (owner, 2026-10-04): the push vtable, built ONCE per root and kept in native
    /// memory (NativeMemory.Alloc, never freed: one per root for the process), so no decode
    /// writes it and the GC cannot move it. Not a static field of the struct type taken by
    /// address: a non-primitive struct static lives in a boxed object on the GC heap, which
    /// compaction may move, so its address is not stable without a pin. The core only reads
    /// the vtable during the call.
    private static readonly ak_dvt_ChunkLeaf* Vt = MakeVt();
    private static ak_dvt_ChunkLeaf* MakeVt()
    {
        var v = (ak_dvt_ChunkLeaf*)NativeMemory.AllocZeroed((nuint)sizeof(ak_dvt_ChunkLeaf));
        v->utf8_skip = AkUtf8Skip.ChunkLeaf_ALL;   // D20: every bit set, G.Str validates (strict)
        v->apply = &ApplyRoot;
        return v;
    }
    /// Step 5b: the pull family's bits, once per root in native memory (the setter copies them).
    private static readonly ak_pvt_ChunkLeaf* Pvt = MakePvt();
    private static ak_pvt_ChunkLeaf* MakePvt() { var v = (ak_pvt_ChunkLeaf*)NativeMemory.AllocZeroed((nuint)sizeof(ak_pvt_ChunkLeaf)); v->utf8_skip = AkUtf8Skip.ChunkLeaf_ALL; return v; }
    private GCHandle _th;
    private int DecodeArmed(byte[] src, int len, int mode, out ChunkLeaf result)
    {
        result = null;
        EnsureDec();
        // Step a2 (i): no ak_dec_err_reset / ak_dec_err: ak_decode_* clears the context's
        // sticky slot on entry and returns it (a host failure reported through ak_fail
        // from a reverse call included), so its return value carries every error.
        int ar = ArmFor(mode);
        if (ar != 0) { Disarm(ar); return ar; }
        var target = new ChunkLeaf();
        // Step a2 (ii): one GCHandle per instance, its Target set for this decode.
        if (!_th.IsAllocated) _th = GCHandle.Alloc(null);
        _th.Target = target;
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
