                byte* b = len == 0 ? one : b0;
                _drun->Target = GCHandle.ToIntPtr(_th);
                _drun->Buf = b;
                _fwd++;
                rc = Abi.ak_decode_ChunkLeaf(_dctx, _drun, b, (nuint)len, Vt);
            }
        }
        finally { _th.Target = null; rc = Disarm(rc); }
        if (rc < 0) return rc;
        result = target;
        return 0;
    }

    /// D21 s8 attribution (HARNESS ONLY): the same push decode through another vtable.
    /// kind 0 `parse`: every callback null but `new_<slot>` (NewZero: the core skips a non-leaf
    /// element whose `new_` is null), utf8_skip all bits (as the reference); kind 1 `noop`:
    /// every callback G.Noop (new_: NewZero); kind 2 `parse-validate`: kind 0 with utf8_skip 0
    /// (the core validates every string).
    public static readonly ak_dvt_ChunkLeaf* VtParse = MakeVtAttr(0), VtNoop = MakeVtAttr(1), VtParseValidate = MakeVtAttr(2);
    private static ak_dvt_ChunkLeaf* MakeVtAttr(int kind)
    {
        var v = (ak_dvt_ChunkLeaf*)NativeMemory.AllocZeroed((nuint)sizeof(ak_dvt_ChunkLeaf));
        v->utf8_skip = kind == 2 ? 0 : AkUtf8Skip.ChunkLeaf_ALL;
        if (kind == 1) *(void**)&v->apply = G.NoopPtr;
        return v;
    }
    /// D21 s8 attribution (HARNESS ONLY): DecodeArmed through `vt`; the graph is the bare
    /// root (the callbacks build nothing) and buffers the callbacks did not take are not
    /// UNDELIVERED here (the arena rewinds at the next decode).
    public int DecodeVt(byte[] src, int len, bool retain, ak_dvt_ChunkLeaf* vt)
    {
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        if (!_th.IsAllocated) _th = GCHandle.Alloc(null);
        int rc;
        fixed (byte* b0 = src)
        fixed (byte* one = One)
        {
            byte* b = len == 0 ? one : b0;
            _drun->Target = GCHandle.ToIntPtr(_th);
            _drun->Buf = b;
            rc = Abi.ak_decode_ChunkLeaf(_dctx, _drun, b, (nuint)len, vt);
        }
        rc = Disarm(rc);
        return rc == UNDELIVERED ? 0 : rc;
    }
    /// D21 s8 attribution (HARNESS ONLY): the pull family's parse alone (no replay).
    public int ParseOnly(byte[] src, int len, bool retain)
    {
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        int rc;
        fixed (byte* b0 = src)
        fixed (byte* one = One)
            rc = Abi.ak_parse_ChunkLeaf(_dctx, len == 0 ? one : b0, (nuint)len);
        rc = Disarm(rc);
        return rc == UNDELIVERED ? 0 : rc;
    }

    /// ABI v1 7.1's PULL family: parse into the context's record stream (no reverse
    /// call but grow), then replay it with the same group readers the push callbacks
    /// use. The context is armed exactly as for push.
    public ChunkLeaf Pull(byte[] src, int len) { int rc = TryPull(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core parse failed: {rc}"); return t; }

    public int TryPull(byte[] src, int len, bool retain, out ChunkLeaf result)
    {
        result = null;
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        var t = new ChunkLeaf();
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                byte* b = len == 0 ? one : b0;
                _fwd++;
                rc = Abi.ak_parse_ChunkLeaf(_dctx, b, (nuint)len);
                if (rc >= 0)
                {
                    byte* recs; nuint rlen;
                    _fwd++;
                    rc = Abi.ak_bdr_ptr(_dctx, &recs, &rlen);
                    if (rc == 0) { try { Replay(t, b, recs, (int)rlen); } catch (DecoderFallbackException) { rc = Abi.AK_ERR_TRANSCODE; } }
                }
            }
        }
        finally { rc = Disarm(rc); }
        if (rc < 0) return rc;
        result = t;
        return 0;
    }

    private const uint OP_APPLY = 1, OP_ADD = 2, OP_NEW = 3, OP_APPLY_ELEM = 4;   // ak_bdr_rec.op
    private static void Replay(ChunkLeaf t, byte* b, byte* p, int len)
    {
        int at = 0;
        while (len - at >= sizeof(ak_bdr_rec))
        {
            ref var r = ref *(ak_bdr_rec*)(p + at);
            byte* body = p + at + sizeof(ak_bdr_rec);
            at += sizeof(ak_bdr_rec) + (int)r.bytes;
            uint outer = r.slot >> 16, inner = r.slot & 0xFFFF;
            switch (r.op)
            {
                case OP_APPLY: G.D_ChunkLeaf(ref *(ak_dfix_ChunkLeaf*)body, t, b); break;
                default: break;
            }
        }
    }

    /// FIX-PLAN D23: the FSM decode family. ak_fsm_begin_ChunkLeaf returns the first
    /// event, ak_fsm_next_ChunkLeaf each next one, each RETURNING the event's op (> 0;
    /// the root APPLY is the last, the end) or an error (< 0); every event is consumed
    /// (FsmDispatch) before the next call, which may overwrite its payload. One `fixed`
    /// spans begin and every next (the core holds spans into the input until the end
    /// event). Arming, Disarm, retain ownership and the failure path are pull's; a
    /// failed decode's partial object is discarded.
    public ChunkLeaf Fsm(byte[] src, int len) { int rc = TryFsm(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core FSM decode failed: {rc}"); return t; }
    /// D23: the FSM's own D20 mask (every bit: G.Str validates), native, copied by its setter
    /// (ak_fsm_set_pvt_<Root>) once, when EnsureDec creates the context.
    private static readonly ak_pvt_ChunkLeaf* FsmPvt = MakeFsmPvt();
    private static ak_pvt_ChunkLeaf* MakeFsmPvt() { var v = (ak_pvt_ChunkLeaf*)NativeMemory.AllocZeroed((nuint)sizeof(ak_pvt_ChunkLeaf)); v->utf8_skip = AkUtf8Skip.ChunkLeaf_ALL; return v; }

    public int TryFsm(byte[] src, int len, bool retain, out ChunkLeaf result)
    {
        result = null;
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        var t = new ChunkLeaf();
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                byte* b = len == 0 ? one : b0;
                ak_fsm_ev ev;
                _fwd++;
                int op = Abi.ak_fsm_begin_ChunkLeaf(_dctx, b, (nuint)len, &ev);
                try
                {
                    while (op > 0)
                    {
                        if (op == (int)Abi.AK_BDR_APPLY)
                        {
                            // The root group: always the last event, the end.
                            G.D_ChunkLeaf(ref *(ak_dfix_ChunkLeaf*)ev.data, t, b);
                            break;
                        }
                        FsmDispatch(t, b, (uint)op, &ev);
                        _fwd++;
                        op = Abi.ak_fsm_next_ChunkLeaf(_dctx, &ev);
                    }
                    rc = op < 0 ? op : 0;
                }
                catch (DecoderFallbackException) { rc = Abi.AK_ERR_TRANSCODE; }
            }
        }
        finally { rc = Disarm(rc); }
        if (rc < 0) return rc;   // the partial object is dropped
        result = t;
        return 0;
    }

    /// D23: one non-final event, `op` the call's return (NEW, ADD, APPLY_ELEM; the root APPLY is the end event,
    /// handled by TryFsm). slot = outer << 16 | inner, pull's numbering: a root-level run
    /// is (0, slot), a non-leaf slot's element is (slot, 0) and its inner runs (slot, inner).
    private static void FsmDispatch(ChunkLeaf t, byte* b, uint op, ak_fsm_ev* ev)
    {
        byte* d = (byte*)ev->data;
        switch (op)
        {
        }
    }

    public long PullFootprint() => _dctx == IntPtr.Zero ? 0 : (long)Abi.ak_bdr_footprint(_dctx);
    public AkCounters EncCounters() { AkCounters c; Abi.ak_enc_counters(_ctx, &c); return c; }
    public void EncCountersReset() => Abi.ak_enc_counters_reset(_ctx);
    public AkCounters DecCounters() { AkCounters c; if (_dctx == IntPtr.Zero) return default; Abi.ak_dec_counters(_dctx, &c); return c; }
    public void DecCountersReset() { if (_dctx != IntPtr.Zero) Abi.ak_dec_counters_reset(_dctx); }

    public void Dispose()
    {
        if (_ctx != IntPtr.Zero) { Abi.ak_enc_ctx_free(_ctx); _ctx = IntPtr.Zero; }
        if (_dctx != IntPtr.Zero) { Abi.ak_dec_ctx_free(_dctx); _dctx = IntPtr.Zero; }
        if (_th.IsAllocated) _th.Free();
        _st.Dispose();
        if (_run != null)
        {
            NativeMemory.Free(_run); _run = null;
        }
        if (_drun != null) { NativeMemory.Free(_drun); _drun = null; }
    }
}

[StructLayout(LayoutKind.Sequential)]
public unsafe struct Run_ChunkInner
{
    public int Chunk;
    public int Retain;
    public void* S_marks; public int N_marks;
    public void* S_leaves; public int N_leaves;
}

/// core-ffi for `ChunkInner`: every group, slot and entry point from the plan.
public sealed unsafe class CoreFfi_ChunkInner : IDisposable
{
    private IntPtr _ctx, _dctx;
    private readonly Stage _st;
    private Run_ChunkInner* _run;
    private DecRun* _drun;
    public int Chunk;
    /// Counted where each crossing happens (R5). Static: an [UnmanagedCallersOnly]
    /// callback cannot reach an instance; one arm at a time.
    private static long _fwd, _rev;
    public long ForwardCalls => _fwd;
    public long ReverseCalls => _rev;
    public void CallsReset() { _fwd = 0; _rev = 0; }
    private int _cap_marks;
    private int _cap_leaves;

    public CoreFfi_ChunkInner(bool utf16 = false)
    {
        _ctx = Abi.ak_enc_ctx_new();
        if (_ctx == IntPtr.Zero) throw new InvalidOperationException("ak_enc_ctx_new returned null");
        _st = new Stage(utf16 || Environment.GetEnvironmentVariable("AK_UTF16") == "1");
        _run = (Run_ChunkInner*)NativeMemory.AllocZeroed((nuint)sizeof(Run_ChunkInner));
    }

    /// E1R / E1C (D21 step 7): the facade root of the encode running on this thread, for the
    /// frames inside the loop callbacks to pin its strings.
    [ThreadStatic] private static ChunkInner _pinSrc;

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static int Loop_marks(IntPtr ctx, void* obj, long token)
    {
        _rev++;
        try
        {
            var run = (Run_ChunkInner*)obj;
            int n = run->N_marks;
            if (n == 0) return 0;
            _fwd++;
            return Abi.ak_run_i64(ctx, (long*)run->S_marks, (nuint)n);
        }
        catch { return Abi.AK_ERR_HOST; }
    }

    /// E1R: one frame per element of the chunk [off, off + k); each `fixed`s every string of
    /// its element, patches the element's marked members, and recurses; the deepest frame
    /// makes the element call, and unwinding releases the pins.
    private static int Rec_leaves(IntPtr ctx, Run_ChunkInner* run, System.Collections.Generic.List<ChunkLeaf> lst, int off, int k, int i)
    {
#if AK_HOST_COUNT
        Stage.Sp(i, (byte*)&i);
#endif
        if (i == k)
        {
            _fwd++;
            return Abi.ak_elem_ChunkLeaf(ctx, (ak_efix_ChunkLeaf*)((ak_efix_ChunkLeaf*)run->S_leaves + off), k);
        }
        var __e = lst[off + i];
        fixed (char* __p0 = __e.K)
        {
            {
                var __g = (ak_efix_ChunkLeaf*)run->S_leaves + off + i;
                if (__g->k.data == Stage.PinPending) { __g->k.data = (IntPtr)__p0; Stage.Patched++; }
            }
            return Rec_leaves(ctx, run, lst, off, k, i + 1);
        }
    }

    /// E1C: the chunk's strings pinned by GCHandles, freed once its element call has returned.
    private static int ChunkH_leaves(IntPtr ctx, Run_ChunkInner* run, System.Collections.Generic.List<ChunkLeaf> lst, int off, int k)
    {
        int __h = Stage.ChunkMark();   // this chunk releases only the handles it adds
        for (int i = 0; i < k; i++)
        {
            var __e = lst[off + i];
            {
                var __g = (ak_efix_ChunkLeaf*)run->S_leaves + off + i;
                if (__g->k.data == Stage.PinPending) { __g->k.data = Stage.PinChunk(__e.K); }
            }
        }
        Stage.BeforeChunkCall(__h);
        _fwd++;
        int rc = Abi.ak_elem_ChunkLeaf(ctx, (ak_efix_ChunkLeaf*)((ak_efix_ChunkLeaf*)run->S_leaves + off), k);
        Stage.ReleaseChunk(__h);
        return rc;
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static int Loop_leaves(IntPtr ctx, void* obj, long token)
    {
        _rev++;
        try
        {
            var run = (Run_ChunkInner*)obj;
            int n = run->N_leaves;
            if (n == 0) return 0;
            int chunk = run->Chunk <= 0 ? n : run->Chunk;
            int d = Stage.DeferNow;
            if (d != 0 && chunk > Stage.PinK) chunk = Stage.PinK;
            for (int off = 0; off < n; off += chunk)
            {
                int k = n - off; if (k > chunk) k = chunk;
                if (d != 0)
                {
                    int rp = d == 1 ? Rec_leaves(ctx, run, _pinSrc.Leaves, off, k, 0) : ChunkH_leaves(ctx, run, _pinSrc.Leaves, off, k);
                    Stage.AfterChunk();
                    if (rp < 0) return rp;
                    continue;
                }
                _fwd++;
                int rc = Abi.ak_elem_ChunkLeaf(ctx, (ak_efix_ChunkLeaf*)((ak_efix_ChunkLeaf*)run->S_leaves + off), k);
                if (rc < 0) return rc;
            }
            return 0;
        }
        catch { return Abi.AK_ERR_HOST; }
    }

    public int Fill(ChunkInner src) { Go(src, false, false, out _, out _); return 0; }
    public void Encode(ChunkInner src, out byte* p, out int len) { int rc = Go(src, false, true, out p, out len); if (rc < 0) throw new InvalidOperationException($"core encode failed: {rc}"); }
    public int TryEncode(ChunkInner src, bool retain, out byte* p, out int len) => Go(src, retain, true, out p, out len);
    /// ABI v1 section 9's move path (WP8): encode and leave the output IN the encode context,
    /// no ak_enc_take, for ak_call_unary_enc / ak_call_send_enc to move as the request body.
    public int EncodeInto(ChunkInner src, bool retain)
    {
        _keep = true;
        try { return Go(src, retain, true, out _, out _); }
        finally { _keep = false; }
    }
    /// A copy of the bytes an EncodeInto left in the context (ak_enc_take reads them without
    /// consuming them); for checks, never on a timed path.
    public byte[] ContextBytes()
    {
        byte* bp; nuint blen;
        int tk = Abi.ak_enc_take(_ctx, &bp, &blen);
        if (tk != 0) throw new InvalidOperationException($"core encode failed: {tk}");
        return new ReadOnlySpan<byte>(bp, (int)blen).ToArray();
    }
    /// The encode context, for the move path's entries.
    public IntPtr EncContext => _ctx;
    private bool _keep;
    public byte[] EncodeToArray(ChunkInner src, bool retain = false)
    {
        int rc = Go(src, retain, true, out byte* p, out int len);
        if (rc < 0) throw new InvalidOperationException($"core encode failed: {rc}");
        var a = new byte[len];
        new ReadOnlySpan<byte>(p, len).CopyTo(a);
        return a;
    }

    private int Go(ChunkInner src, bool retain, bool call, out byte* outPtr, out int outLen)
    {
        outPtr = null; outLen = 0;
        Abi.ak_enc_reset(_ctx);
        _st.Reset();
        int __d = Stage.Defer;   // E1R / E1C: read once; the default path tests this local only
        long __mk0 = 0, __pt0 = 0;
        if (__d != 0) { __mk0 = Stage.Marked; __pt0 = Stage.Patched; }   // this encode's marks and patches
        _run->Chunk = Chunk;
        if (retain) throw new NotSupportedException("unknown fields are compiled out of this build (WP5 step 10): no ak_uencode");
        {
            var lst = src.Marks;
            int n = lst == null ? 0 : lst.Count;
            _run->N_marks = n;
            Arr.Ensure(ref _run->S_marks, ref _cap_marks, n, sizeof(long));
            for (int i = 0; i < n; i++)
            {
                ((long*)_run->S_marks)[i] = lst[i];
            }
        }
        {
            var lst = src.Leaves;
            int n = lst == null ? 0 : lst.Count;
            _run->N_leaves = n;
            Arr.Ensure(ref _run->S_leaves, ref _cap_leaves, n, sizeof(ak_efix_ChunkLeaf));
            for (int i = 0; i < n; i++)
            {
                G.E_ChunkLeaf(ref ((ak_efix_ChunkLeaf*)_run->S_leaves)[i], lst[i], _st);
            }
        }
        var vt = new ak_evt_ChunkInner
        {
            loop_marks = &Loop_marks,
            loop_leaves = &Loop_leaves,
        };
        nint rc;
        {
            var fix = new ak_efix_ChunkInner();
            G.E_ChunkInner(ref fix, src, _st);
            if (!call) return 0;
            _fwd++;
            if (__d != 0) { if (Stage.Marked == __mk0) __d = 0; else { _pinSrc = src; Stage.DeferNow = __d; } }
            rc = Abi.ak_encode_ChunkInner(_run, _ctx, &vt, &fix);
        }
        _st.ReleasePins();   // D21 E1: the core has copied every pinned string
        if (__d != 0)
        {
            Stage.DeferNow = 0;   // the next encode on this thread starts from the default
            _pinSrc = null;
            // E1R / E1C: every mark the fill left was patched by a frame before the core read it.
            if (Stage.Marked - __mk0 != Stage.Patched - __pt0 && rc >= 0) rc = Abi.AK_ERR_HOST;
        }
        if (rc < 0) return (int)rc;
        if (_keep) return 0;   // EncodeInto: the output stays in the context (the move path)
        byte* bp; nuint blen;
        int tk = Abi.ak_enc_take(_ctx, &bp, &blen);
        if (tk != 0) return tk;
        outPtr = bp; outLen = (int)blen;
        return 0;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct DecRun { public IntPtr Target; public byte* Buf; }

    private static ChunkInner Tgt(void* obj) => (ChunkInner)GCHandle.FromIntPtr(((DecRun*)obj)->Target).Target;

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void ApplyRoot(IntPtr ctx, void* obj, ak_dfix_ChunkInner* fix)
    {
        _rev++;
        try { if (G.PlantHostFail == 1) throw new InvalidOperationException("planted host failure (apply)"); G.D_ChunkInner(ref *fix, Tgt(obj), ((DecRun*)obj)->Buf); }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_marks(IntPtr ctx, void* obj, long token, long* xs, int n)
    {
        _rev++;
        try
        {
            if (G.PlantHostFail == 2) throw new InvalidOperationException("planted host failure (add)");
            byte* b = ((DecRun*)obj)->Buf;
            var lst = Tgt(obj).Marks;
            lst.EnsureCapacity(lst.Count + n);   // step 9a: the run's count is known
            for (int i = 0; i < n; i++) lst.Add(xs[i]);
        }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_leaves(IntPtr ctx, void* obj, long token, ak_dfix_ChunkLeaf* xs, int n)
    {
        _rev++;
        try
        {
            if (G.PlantHostFail == 2) throw new InvalidOperationException("planted host failure (add)");
            byte* b = ((DecRun*)obj)->Buf;
            var lst = Tgt(obj).Leaves;
            lst.EnsureCapacity(lst.Count + n);   // step 9a: the run's count is known
            for (int i = 0; i < n; i++) { var x = new ChunkLeaf(); G.D_ChunkLeaf(ref xs[i], x, b); lst.Add(x); }
        }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    private static readonly byte[] One = new byte[1];

    /// WP5 step 10: this build has unknown fields COMPILED OUT (no options, no resets).
    public const bool UnknownCompiledOut = true;
    public const int UNDELIVERED = -1001;   // never returned by this build
    public int Undelivered => 0;
    public long ResetCalls => 0;

    private void EnsureDec()
    {
        if (_dctx != IntPtr.Zero) return;
        _dctx = Abi.ak_dec_ctx_new_ChunkInner();   // rule 6: bound to this root; no options exist
        if (_dctx == IntPtr.Zero) throw new InvalidOperationException("ak_dec_ctx_new_ChunkInner returned NULL");
        // D20: the pull family's bits, copied into this root-bound context (every bit: G.Str validates).
        int sp = Abi.ak_dec_set_pvt_ChunkInner(_dctx, Pvt);   // step 5b: the root's one native pvt
        if (sp != 0) throw new InvalidOperationException("ak_dec_set_pvt_ChunkInner: " + sp);
        // D23 / D24: the FSM's own D20 mask, copied once into the context when it is created (set
        // lazily on the first FSM decode, it made one count row depend on which thread decoded).
        int fp = Abi.ak_fsm_set_pvt_ChunkInner(_dctx, FsmPvt);
        if (fp != 0) throw new InvalidOperationException("ak_fsm_set_pvt_ChunkInner: " + fp);
        _drun = (DecRun*)NativeMemory.AllocZeroed((nuint)sizeof(DecRun));
    }

    private int ArmFor(int mode) => mode == -2 ? 0 : throw new NotSupportedException("unknown fields are compiled out of this build (WP5 step 10)");
    private int Disarm(int rc) => rc;

    public ChunkInner Decode(byte[] src, int len) { int rc = TryDecode(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core decode failed: {rc}"); return t; }

    /// The core's code (< 0) on failure; the output is then unspecified and discarded (R-G6).
    public int TryDecode(byte[] src, int len, bool retain, out ChunkInner result) => DecodeArmed(src, len, retain ? -1 : -2, out result);

    /// Step 5b (owner, 2026-10-04): the push vtable, built ONCE per root and kept in native
    /// memory (NativeMemory.Alloc, never freed: one per root for the process), so no decode
    /// writes it and the GC cannot move it. Not a static field of the struct type taken by
    /// address: a non-primitive struct static lives in a boxed object on the GC heap, which
    /// compaction may move, so its address is not stable without a pin. The core only reads
    /// the vtable during the call.
    private static readonly ak_dvt_ChunkInner* Vt = MakeVt();
    private static ak_dvt_ChunkInner* MakeVt()
    {
        var v = (ak_dvt_ChunkInner*)NativeMemory.AllocZeroed((nuint)sizeof(ak_dvt_ChunkInner));
        v->utf8_skip = AkUtf8Skip.ChunkInner_ALL;   // D20: every bit set, G.Str validates (strict)
        v->apply = &ApplyRoot;
        v->add_marks = &Add_marks;
        v->add_leaves = &Add_leaves;
        return v;
    }
    /// Step 5b: the pull family's bits, once per root in native memory (the setter copies them).
    private static readonly ak_pvt_ChunkInner* Pvt = MakePvt();
    private static ak_pvt_ChunkInner* MakePvt() { var v = (ak_pvt_ChunkInner*)NativeMemory.AllocZeroed((nuint)sizeof(ak_pvt_ChunkInner)); v->utf8_skip = AkUtf8Skip.ChunkInner_ALL; return v; }
    private GCHandle _th;
    private int DecodeArmed(byte[] src, int len, int mode, out ChunkInner result)
    {
        result = null;
        EnsureDec();
        // Step a2 (i): no ak_dec_err_reset / ak_dec_err: ak_decode_* clears the context's
        // sticky slot on entry and returns it (a host failure reported through ak_fail
        // from a reverse call included), so its return value carries every error.
        int ar = ArmFor(mode);
        if (ar != 0) { Disarm(ar); return ar; }
        var target = new ChunkInner();
        // Step a2 (ii): one GCHandle per instance, its Target set for this decode.
        if (!_th.IsAllocated) _th = GCHandle.Alloc(null);
        _th.Target = target;
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                // (NULL, 0) is never handed to the core: an empty buffer is a valid pointer and 0.
                byte* b = len == 0 ? one : b0;
                _drun->Target = GCHandle.ToIntPtr(_th);
                _drun->Buf = b;
                _fwd++;
                rc = Abi.ak_decode_ChunkInner(_dctx, _drun, b, (nuint)len, Vt);
            }
        }
        finally { _th.Target = null; rc = Disarm(rc); }
        if (rc < 0) return rc;
        result = target;
        return 0;
    }

    /// D21 s8 attribution (HARNESS ONLY): the same push decode through another vtable.
    /// kind 0 `parse`: every callback null but `new_<slot>` (NewZero: the core skips a non-leaf
    /// element whose `new_` is null), utf8_skip all bits (as the reference); kind 1 `noop`:
    /// every callback G.Noop (new_: NewZero); kind 2 `parse-validate`: kind 0 with utf8_skip 0
    /// (the core validates every string).
    public static readonly ak_dvt_ChunkInner* VtParse = MakeVtAttr(0), VtNoop = MakeVtAttr(1), VtParseValidate = MakeVtAttr(2);
    private static ak_dvt_ChunkInner* MakeVtAttr(int kind)
    {
        var v = (ak_dvt_ChunkInner*)NativeMemory.AllocZeroed((nuint)sizeof(ak_dvt_ChunkInner));
        v->utf8_skip = kind == 2 ? 0 : AkUtf8Skip.ChunkInner_ALL;
        if (kind == 1) *(void**)&v->apply = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_marks = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_leaves = G.NoopPtr;
        return v;
    }
    /// D21 s8 attribution (HARNESS ONLY): DecodeArmed through `vt`; the graph is the bare
    /// root (the callbacks build nothing) and buffers the callbacks did not take are not
    /// UNDELIVERED here (the arena rewinds at the next decode).
    public int DecodeVt(byte[] src, int len, bool retain, ak_dvt_ChunkInner* vt)
    {
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        if (!_th.IsAllocated) _th = GCHandle.Alloc(null);
        int rc;
        fixed (byte* b0 = src)
        fixed (byte* one = One)
        {
            byte* b = len == 0 ? one : b0;
            _drun->Target = GCHandle.ToIntPtr(_th);
            _drun->Buf = b;
            rc = Abi.ak_decode_ChunkInner(_dctx, _drun, b, (nuint)len, vt);
        }
        rc = Disarm(rc);
        return rc == UNDELIVERED ? 0 : rc;
    }
    /// D21 s8 attribution (HARNESS ONLY): the pull family's parse alone (no replay).
    public int ParseOnly(byte[] src, int len, bool retain)
    {
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        int rc;
        fixed (byte* b0 = src)
        fixed (byte* one = One)
            rc = Abi.ak_parse_ChunkInner(_dctx, len == 0 ? one : b0, (nuint)len);
        rc = Disarm(rc);
        return rc == UNDELIVERED ? 0 : rc;
    }

    /// ABI v1 7.1's PULL family: parse into the context's record stream (no reverse
    /// call but grow), then replay it with the same group readers the push callbacks
    /// use. The context is armed exactly as for push.
    public ChunkInner Pull(byte[] src, int len) { int rc = TryPull(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core parse failed: {rc}"); return t; }

    public int TryPull(byte[] src, int len, bool retain, out ChunkInner result)
    {
        result = null;
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        var t = new ChunkInner();
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                byte* b = len == 0 ? one : b0;
                _fwd++;
                rc = Abi.ak_parse_ChunkInner(_dctx, b, (nuint)len);
                if (rc >= 0)
                {
                    byte* recs; nuint rlen;
                    _fwd++;
                    rc = Abi.ak_bdr_ptr(_dctx, &recs, &rlen);
                    if (rc == 0) { try { Replay(t, b, recs, (int)rlen); } catch (DecoderFallbackException) { rc = Abi.AK_ERR_TRANSCODE; } }
                }
            }
        }
        finally { rc = Disarm(rc); }
        if (rc < 0) return rc;
        result = t;
        return 0;
    }

    private const uint OP_APPLY = 1, OP_ADD = 2, OP_NEW = 3, OP_APPLY_ELEM = 4;   // ak_bdr_rec.op
    private static void Replay(ChunkInner t, byte* b, byte* p, int len)
    {
        int at = 0;
        while (len - at >= sizeof(ak_bdr_rec))
        {
            ref var r = ref *(ak_bdr_rec*)(p + at);
            byte* body = p + at + sizeof(ak_bdr_rec);
            at += sizeof(ak_bdr_rec) + (int)r.bytes;
            uint outer = r.slot >> 16, inner = r.slot & 0xFFFF;
            switch (r.op)
            {
                case OP_APPLY: G.D_ChunkInner(ref *(ak_dfix_ChunkInner*)body, t, b); break;
                case OP_ADD when outer == 0 && inner == 1:   // a root-level run
                {
                    var xs = (long*)body; var lst = t.Marks;
                    lst.EnsureCapacity(lst.Count + (int)r.n);   // step 9a: the run's count is known
                    for (int i = 0; i < (int)r.n; i++) lst.Add(xs[i]);
                    break;
                }
                case OP_ADD when outer == 0 && inner == 2:   // a root-level run
                {
                    var xs = (ak_dfix_ChunkLeaf*)body; var lst = t.Leaves;
                    lst.EnsureCapacity(lst.Count + (int)r.n);   // step 9a: the run's count is known
                    for (int i = 0; i < (int)r.n; i++) { var x = new ChunkLeaf(); G.D_ChunkLeaf(ref xs[i], x, b); lst.Add(x); }
                    break;
                }
                default: break;
            }
        }
    }

    /// FIX-PLAN D23: the FSM decode family. ak_fsm_begin_ChunkInner returns the first
    /// event, ak_fsm_next_ChunkInner each next one, each RETURNING the event's op (> 0;
    /// the root APPLY is the last, the end) or an error (< 0); every event is consumed
    /// (FsmDispatch) before the next call, which may overwrite its payload. One `fixed`
    /// spans begin and every next (the core holds spans into the input until the end
    /// event). Arming, Disarm, retain ownership and the failure path are pull's; a
    /// failed decode's partial object is discarded.
    public ChunkInner Fsm(byte[] src, int len) { int rc = TryFsm(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core FSM decode failed: {rc}"); return t; }
    /// D23: the FSM's own D20 mask (every bit: G.Str validates), native, copied by its setter
    /// (ak_fsm_set_pvt_<Root>) once, when EnsureDec creates the context.
    private static readonly ak_pvt_ChunkInner* FsmPvt = MakeFsmPvt();
    private static ak_pvt_ChunkInner* MakeFsmPvt() { var v = (ak_pvt_ChunkInner*)NativeMemory.AllocZeroed((nuint)sizeof(ak_pvt_ChunkInner)); v->utf8_skip = AkUtf8Skip.ChunkInner_ALL; return v; }

    public int TryFsm(byte[] src, int len, bool retain, out ChunkInner result)
    {
        result = null;
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        var t = new ChunkInner();
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                byte* b = len == 0 ? one : b0;
                ak_fsm_ev ev;
                _fwd++;
                int op = Abi.ak_fsm_begin_ChunkInner(_dctx, b, (nuint)len, &ev);
                try
                {
                    while (op > 0)
                    {
                        if (op == (int)Abi.AK_BDR_APPLY)
                        {
                            // The root group: always the last event, the end.
                            G.D_ChunkInner(ref *(ak_dfix_ChunkInner*)ev.data, t, b);
                            break;
                        }
                        FsmDispatch(t, b, (uint)op, &ev);
                        _fwd++;
                        op = Abi.ak_fsm_next_ChunkInner(_dctx, &ev);
                    }
                    rc = op < 0 ? op : 0;
                }
                catch (DecoderFallbackException) { rc = Abi.AK_ERR_TRANSCODE; }
            }
        }
        finally { rc = Disarm(rc); }
        if (rc < 0) return rc;   // the partial object is dropped
        result = t;
        return 0;
    }

    /// D23: one non-final event, `op` the call's return (NEW, ADD, APPLY_ELEM; the root APPLY is the end event,
    /// handled by TryFsm). slot = outer << 16 | inner, pull's numbering: a root-level run
    /// is (0, slot), a non-leaf slot's element is (slot, 0) and its inner runs (slot, inner).
    private static void FsmDispatch(ChunkInner t, byte* b, uint op, ak_fsm_ev* ev)
    {
        byte* d = (byte*)ev->data;
        switch (op)
        {
            case Abi.AK_BDR_ADD:
                switch (ev->slot)
                {
                    case 1u:   // a root-level run
                    {
                        var xs = (long*)d; var lst = t.Marks; int n = (int)ev->n;
                        lst.EnsureCapacity(lst.Count + n);
                        for (int i = 0; i < n; i++) lst.Add(xs[i]);
                        return;
                    }
                    case 2u:   // a root-level run
                    {
                        var xs = (ak_dfix_ChunkLeaf*)d; var lst = t.Leaves; int n = (int)ev->n;
                        lst.EnsureCapacity(lst.Count + n);
                        for (int i = 0; i < n; i++) { var x = new ChunkLeaf(); G.D_ChunkLeaf(ref xs[i], x, b); lst.Add(x); }
                        return;
                    }
                }
                return;
        }
    }

    public long PullFootprint() => _dctx == IntPtr.Zero ? 0 : (long)Abi.ak_bdr_footprint(_dctx);
    public AkCounters EncCounters() { AkCounters c; Abi.ak_enc_counters(_ctx, &c); return c; }
    public void EncCountersReset() => Abi.ak_enc_counters_reset(_ctx);
    public AkCounters DecCounters() { AkCounters c; if (_dctx == IntPtr.Zero) return default; Abi.ak_dec_counters(_dctx, &c); return c; }
    public void DecCountersReset() { if (_dctx != IntPtr.Zero) Abi.ak_dec_counters_reset(_dctx); }

    public void Dispose()
    {
        if (_ctx != IntPtr.Zero) { Abi.ak_enc_ctx_free(_ctx); _ctx = IntPtr.Zero; }
        if (_dctx != IntPtr.Zero) { Abi.ak_dec_ctx_free(_dctx); _dctx = IntPtr.Zero; }
        if (_th.IsAllocated) _th.Free();
        _st.Dispose();
        if (_run != null)
        {
            NativeMemory.Free(_run->S_marks);
            NativeMemory.Free(_run->S_leaves);
            NativeMemory.Free(_run); _run = null;
        }
        if (_drun != null) { NativeMemory.Free(_drun); _drun = null; }
    }
}

[StructLayout(LayoutKind.Sequential)]
public unsafe struct Run_ChunkElement
{
    public int Chunk;
    public int Retain;
    public void* S_labels; public int N_labels;
    public void* S_attrs; public int N_attrs;
    public void* S_inner_marks; public int N_inner_marks;
    public void* S_inner_leaves; public int N_inner_leaves;
}

/// core-ffi for `ChunkElement`: every group, slot and entry point from the plan.
public sealed unsafe class CoreFfi_ChunkElement : IDisposable
{
    private IntPtr _ctx, _dctx;
    private readonly Stage _st;
    private Run_ChunkElement* _run;
    private DecRun* _drun;
    public int Chunk;
    /// Counted where each crossing happens (R5). Static: an [UnmanagedCallersOnly]
    /// callback cannot reach an instance; one arm at a time.
    private static long _fwd, _rev;
    public long ForwardCalls => _fwd;
    public long ReverseCalls => _rev;
    public void CallsReset() { _fwd = 0; _rev = 0; }
    private int _cap_labels;
    private int _cap_attrs;
    private int _cap_inner_marks;
    private int _cap_inner_leaves;

    public CoreFfi_ChunkElement(bool utf16 = false)
    {
        _ctx = Abi.ak_enc_ctx_new();
        if (_ctx == IntPtr.Zero) throw new InvalidOperationException("ak_enc_ctx_new returned null");
        _st = new Stage(utf16 || Environment.GetEnvironmentVariable("AK_UTF16") == "1");
        _run = (Run_ChunkElement*)NativeMemory.AllocZeroed((nuint)sizeof(Run_ChunkElement));
    }

    /// E1R / E1C (D21 step 7): the facade root of the encode running on this thread, for the
    /// frames inside the loop callbacks to pin its strings.
    [ThreadStatic] private static ChunkElement _pinSrc;

    /// E1R: one frame per string of [off, off + k) of a repeated string field; the deepest
    /// frame makes the chunk's ak_blob_run.
    private static int RecS_labels(IntPtr ctx, ak_str* arr, System.Collections.Generic.List<string> l, int off, int k, int j)
    {
#if AK_HOST_COUNT
        Stage.Sp(j, (byte*)&j);
#endif
        if (j == k) { _fwd++; return Abi.ak_blob_run(ctx, arr + off, k); }
        fixed (char* __p = l[off + j])
        {
            if (arr[off + j].data == Stage.PinPending) { arr[off + j].data = (IntPtr)__p; Stage.Patched++; Stage.RepPatched++; }
            return RecS_labels(ctx, arr, l, off, k, j + 1);
        }
    }

    private static int ChunkHS_labels(IntPtr ctx, ak_str* arr, System.Collections.Generic.List<string> l, int off, int k)
    {
        int __h = Stage.ChunkMark();   // this chunk releases only the handles it adds
        for (int j = 0; j < k; j++) if (arr[off + j].data == Stage.PinPending) { arr[off + j].data = Stage.PinChunk(l[off + j]); Stage.RepPatched++; }
        Stage.BeforeChunkCall(__h);
        _fwd++;
        int rc = Abi.ak_blob_run(ctx, arr + off, k);
        Stage.ReleaseChunk(__h);
        return rc;
    }

    private static int PinStrs_labels(IntPtr ctx, ak_str* arr, System.Collections.Generic.List<string> l, int n)
    {
        int K = Stage.PinK, d = Stage.DeferNow;
        for (int off = 0; off < n; off += K)
        {
            int k = n - off; if (k > K) k = K;
            int rc = d == 1 ? RecS_labels(ctx, arr, l, off, k, 0) : ChunkHS_labels(ctx, arr, l, off, k);
            Stage.AfterChunk();
            if (rc < 0) return rc;
        }
        return 0;
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static int Loop_labels(IntPtr ctx, void* obj, long token)
    {
        _rev++;
        try
        {
            var run = (Run_ChunkElement*)obj;
            int n = run->N_labels;
            if (n == 0) return 0;
            if (Stage.DeferNow != 0) return PinStrs_labels(ctx, (ak_str*)run->S_labels, _pinSrc.Labels, n);
            _fwd++;
            return Abi.ak_blob_run(ctx, (ak_str*)run->S_labels, n);
        }
        catch { return Abi.AK_ERR_HOST; }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static int Loop_attrs(IntPtr ctx, void* obj, long token)
    {
        _rev++;
        try
        {
            var run = (Run_ChunkElement*)obj;
            int n = run->N_attrs;
            if (n == 0) return 0;
            _fwd++;
            return Abi.ak_elem_ChunkElementAttrsEntry(ctx, (ak_efix_ChunkElementAttrsEntry*)run->S_attrs, n);
        }
        catch { return Abi.AK_ERR_HOST; }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static int Loop_inner_marks(IntPtr ctx, void* obj, long token)
    {
        _rev++;
        try
        {
            var run = (Run_ChunkElement*)obj;
            int n = run->N_inner_marks;
            if (n == 0) return 0;
            _fwd++;
            return Abi.ak_run_i64(ctx, (long*)run->S_inner_marks, (nuint)n);
        }
        catch { return Abi.AK_ERR_HOST; }
    }

    /// E1R: one frame per element of the chunk [off, off + k); each `fixed`s every string of
    /// its element, patches the element's marked members, and recurses; the deepest frame
    /// makes the element call, and unwinding releases the pins.
    private static int Rec_inner_leaves(IntPtr ctx, Run_ChunkElement* run, System.Collections.Generic.List<ChunkLeaf> lst, int off, int k, int i)
    {
#if AK_HOST_COUNT
        Stage.Sp(i, (byte*)&i);
#endif
        if (i == k)
        {
            _fwd++;
            return Abi.ak_elem_ChunkLeaf(ctx, (ak_efix_ChunkLeaf*)((ak_efix_ChunkLeaf*)run->S_inner_leaves + off), k);
        }
        var __e = lst[off + i];
        fixed (char* __p0 = __e.K)
        {
            {
                var __g = (ak_efix_ChunkLeaf*)run->S_inner_leaves + off + i;
                if (__g->k.data == Stage.PinPending) { __g->k.data = (IntPtr)__p0; Stage.Patched++; }
            }
            return Rec_inner_leaves(ctx, run, lst, off, k, i + 1);
        }
    }

    /// E1C: the chunk's strings pinned by GCHandles, freed once its element call has returned.
    private static int ChunkH_inner_leaves(IntPtr ctx, Run_ChunkElement* run, System.Collections.Generic.List<ChunkLeaf> lst, int off, int k)
    {
        int __h = Stage.ChunkMark();   // this chunk releases only the handles it adds
        for (int i = 0; i < k; i++)
        {
            var __e = lst[off + i];
            {
                var __g = (ak_efix_ChunkLeaf*)run->S_inner_leaves + off + i;
                if (__g->k.data == Stage.PinPending) { __g->k.data = Stage.PinChunk(__e.K); }
            }
        }
        Stage.BeforeChunkCall(__h);
        _fwd++;
        int rc = Abi.ak_elem_ChunkLeaf(ctx, (ak_efix_ChunkLeaf*)((ak_efix_ChunkLeaf*)run->S_inner_leaves + off), k);
        Stage.ReleaseChunk(__h);
        return rc;
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static int Loop_inner_leaves(IntPtr ctx, void* obj, long token)
    {
        _rev++;
        try
        {
            var run = (Run_ChunkElement*)obj;
            int n = run->N_inner_leaves;
            if (n == 0) return 0;
            int chunk = run->Chunk <= 0 ? n : run->Chunk;
            int d = Stage.DeferNow;
            if (d != 0 && chunk > Stage.PinK) chunk = Stage.PinK;
            for (int off = 0; off < n; off += chunk)
            {
                int k = n - off; if (k > chunk) k = chunk;
                if (d != 0)
                {
                    int rp = d == 1 ? Rec_inner_leaves(ctx, run, _pinSrc.Inner?.Leaves, off, k, 0) : ChunkH_inner_leaves(ctx, run, _pinSrc.Inner?.Leaves, off, k);
                    Stage.AfterChunk();
                    if (rp < 0) return rp;
                    continue;
                }
                _fwd++;
                int rc = Abi.ak_elem_ChunkLeaf(ctx, (ak_efix_ChunkLeaf*)((ak_efix_ChunkLeaf*)run->S_inner_leaves + off), k);
                if (rc < 0) return rc;
            }
            return 0;
        }
        catch { return Abi.AK_ERR_HOST; }
    }

    public int Fill(ChunkElement src) { Go(src, false, false, out _, out _); return 0; }
    public void Encode(ChunkElement src, out byte* p, out int len) { int rc = Go(src, false, true, out p, out len); if (rc < 0) throw new InvalidOperationException($"core encode failed: {rc}"); }
    public int TryEncode(ChunkElement src, bool retain, out byte* p, out int len) => Go(src, retain, true, out p, out len);
    /// ABI v1 section 9's move path (WP8): encode and leave the output IN the encode context,
    /// no ak_enc_take, for ak_call_unary_enc / ak_call_send_enc to move as the request body.
    public int EncodeInto(ChunkElement src, bool retain)
    {
        _keep = true;
        try { return Go(src, retain, true, out _, out _); }
        finally { _keep = false; }
    }
    /// A copy of the bytes an EncodeInto left in the context (ak_enc_take reads them without
    /// consuming them); for checks, never on a timed path.
    public byte[] ContextBytes()
    {
        byte* bp; nuint blen;
        int tk = Abi.ak_enc_take(_ctx, &bp, &blen);
        if (tk != 0) throw new InvalidOperationException($"core encode failed: {tk}");
        return new ReadOnlySpan<byte>(bp, (int)blen).ToArray();
    }
    /// The encode context, for the move path's entries.
    public IntPtr EncContext => _ctx;
    private bool _keep;
    public byte[] EncodeToArray(ChunkElement src, bool retain = false)
    {
        int rc = Go(src, retain, true, out byte* p, out int len);
        if (rc < 0) throw new InvalidOperationException($"core encode failed: {rc}");
        var a = new byte[len];
        new ReadOnlySpan<byte>(p, len).CopyTo(a);
        return a;
    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    private static nint RootPinR_e(Run_ChunkElement* _run, IntPtr _ctx, ak_evt_ChunkElement* vt, ak_efix_ChunkElement* __g, ChunkElement src)
    {
        fixed (char* __p0 = src.Id)
        {
            if (__g->id.data == Stage.PinPending) { __g->id.data = (IntPtr)__p0; Stage.Patched++; }
            return Abi.ak_encode_ChunkElement(_run, _ctx, vt, __g);
        }
    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    private static nint RootPinH_e(Run_ChunkElement* _run, IntPtr _ctx, ak_evt_ChunkElement* vt, ak_efix_ChunkElement* __g, ChunkElement src)
    {
        int __h = Stage.ChunkMark();   // this chunk releases only the handles it adds
        if (__g->id.data == Stage.PinPending) { __g->id.data = Stage.PinChunk(src.Id); }
        nint rc;
        rc = Abi.ak_encode_ChunkElement(_run, _ctx, vt, __g);
        Stage.ReleaseChunk(__h);
        return rc;
    }

    private int Go(ChunkElement src, bool retain, bool call, out byte* outPtr, out int outLen)
    {
        outPtr = null; outLen = 0;
        Abi.ak_enc_reset(_ctx);
        _st.Reset();
        int __d = Stage.Defer;   // E1R / E1C: read once; the default path tests this local only
        long __mk0 = 0, __pt0 = 0;
        if (__d != 0) { __mk0 = Stage.Marked; __pt0 = Stage.Patched; }   // this encode's marks and patches
        _run->Chunk = Chunk;
        if (retain) throw new NotSupportedException("unknown fields are compiled out of this build (WP5 step 10): no ak_uencode");
        {
            var lst = src.Labels;
            int n = lst == null ? 0 : lst.Count;
            _run->N_labels = n;
            Arr.Ensure(ref _run->S_labels, ref _cap_labels, n, sizeof(ak_str));
            for (int i = 0; i < n; i++)
            {
                ((ak_str*)_run->S_labels)[i] = _st.Str(lst[i]);
            }
        }
        {
            var lst = src.Attrs;
            int n = lst == null ? 0 : lst.Count;
            _run->N_attrs = n;
            Arr.Ensure(ref _run->S_attrs, ref _cap_attrs, n, sizeof(ak_efix_ChunkElementAttrsEntry));
            var ord = n == 0 ? null : Arr.Utf8Order(lst);
            for (int i = 0; i < n; i++) { var kv = lst.At(ord[i]); { ref var e = ref ((ak_efix_ChunkElementAttrsEntry*)_run->S_attrs)[i]; e = default; e.key = _st.StrH(kv.Key); e.value = _st.StrH(kv.Value); } }
        }
        {
            var lst = src.Inner?.Marks;
            int n = lst == null ? 0 : lst.Count;
            _run->N_inner_marks = n;
            Arr.Ensure(ref _run->S_inner_marks, ref _cap_inner_marks, n, sizeof(long));
            for (int i = 0; i < n; i++)
            {
                ((long*)_run->S_inner_marks)[i] = lst[i];
            }
        }
        {
            var lst = src.Inner?.Leaves;
            int n = lst == null ? 0 : lst.Count;
            _run->N_inner_leaves = n;
            Arr.Ensure(ref _run->S_inner_leaves, ref _cap_inner_leaves, n, sizeof(ak_efix_ChunkLeaf));
            for (int i = 0; i < n; i++)
            {
                G.E_ChunkLeaf(ref ((ak_efix_ChunkLeaf*)_run->S_inner_leaves)[i], lst[i], _st);
            }
        }
        var vt = new ak_evt_ChunkElement
        {
            loop_labels = &Loop_labels,
            loop_attrs = &Loop_attrs,
            loop_inner_marks = &Loop_inner_marks,
            loop_inner_leaves = &Loop_inner_leaves,
        };
        nint rc;
        {
            var fix = new ak_efix_ChunkElement();
            G.E_ChunkElement(ref fix, src, _st);
            if (!call) return 0;
            _fwd++;
            if (__d != 0) { if (Stage.Marked == __mk0) __d = 0; else { _pinSrc = src; Stage.DeferNow = __d; } }
            if (__d == 0) rc = Abi.ak_encode_ChunkElement(_run, _ctx, &vt, &fix);
            else rc = __d == 1 ? RootPinR_e(_run, _ctx, &vt, &fix, src) : RootPinH_e(_run, _ctx, &vt, &fix, src);
        }
        _st.ReleasePins();   // D21 E1: the core has copied every pinned string
        if (__d != 0)
        {
            Stage.DeferNow = 0;   // the next encode on this thread starts from the default
            _pinSrc = null;
            // E1R / E1C: every mark the fill left was patched by a frame before the core read it.
            if (Stage.Marked - __mk0 != Stage.Patched - __pt0 && rc >= 0) rc = Abi.AK_ERR_HOST;
        }
        if (rc < 0) return (int)rc;
        if (_keep) return 0;   // EncodeInto: the output stays in the context (the move path)
        byte* bp; nuint blen;
        int tk = Abi.ak_enc_take(_ctx, &bp, &blen);
        if (tk != 0) return tk;
        outPtr = bp; outLen = (int)blen;
        return 0;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct DecRun { public IntPtr Target; public byte* Buf; }

    private static ChunkElement Tgt(void* obj) => (ChunkElement)GCHandle.FromIntPtr(((DecRun*)obj)->Target).Target;

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void ApplyRoot(IntPtr ctx, void* obj, ak_dfix_ChunkElement* fix)
    {
        _rev++;
        try { if (G.PlantHostFail == 1) throw new InvalidOperationException("planted host failure (apply)"); G.D_ChunkElement(ref *fix, Tgt(obj), ((DecRun*)obj)->Buf); }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_labels(IntPtr ctx, void* obj, long token, ak_span* xs, int n)
    {
        _rev++;
        try
        {
            if (G.PlantHostFail == 2) throw new InvalidOperationException("planted host failure (add)");
            byte* b = ((DecRun*)obj)->Buf;
            var lst = Tgt(obj).Labels;
            lst.EnsureCapacity(lst.Count + n);   // step 9a: the run's count is known
            for (int i = 0; i < n; i++) lst.Add(G.Str(b, xs[i]));
        }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_attrs(IntPtr ctx, void* obj, long token, ak_dfix_ChunkElementAttrsEntry* xs, int n)
    {
        _rev++;
        try
        {
            if (G.PlantHostFail == 2) throw new InvalidOperationException("planted host failure (add)");
            byte* b = ((DecRun*)obj)->Buf;
            var lst = Tgt(obj).Attrs;
            lst.EnsureCapacity(lst.Count + n);   // step 9a: the run's count is known
            // plan: a duplicate key replaces the earlier value.
            for (int i = 0; i < n; i++) lst[G.Str(b, xs[i].key)] = G.Str(b, xs[i].value);
        }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_inner_marks(IntPtr ctx, void* obj, long token, long* xs, int n)
    {
        _rev++;
        try
        {
            if (G.PlantHostFail == 2) throw new InvalidOperationException("planted host failure (add)");
            byte* b = ((DecRun*)obj)->Buf;
            var lst = (Tgt(obj).Inner ??= new ChunkInner()).Marks;
            lst.EnsureCapacity(lst.Count + n);   // step 9a: the run's count is known
            for (int i = 0; i < n; i++) lst.Add(xs[i]);
        }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_inner_leaves(IntPtr ctx, void* obj, long token, ak_dfix_ChunkLeaf* xs, int n)
    {
        _rev++;
        try
        {
            if (G.PlantHostFail == 2) throw new InvalidOperationException("planted host failure (add)");
            byte* b = ((DecRun*)obj)->Buf;
            var lst = (Tgt(obj).Inner ??= new ChunkInner()).Leaves;
            lst.EnsureCapacity(lst.Count + n);   // step 9a: the run's count is known
            for (int i = 0; i < n; i++) { var x = new ChunkLeaf(); G.D_ChunkLeaf(ref xs[i], x, b); lst.Add(x); }
        }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    private static readonly byte[] One = new byte[1];

    /// WP5 step 10: this build has unknown fields COMPILED OUT (no options, no resets).
    public const bool UnknownCompiledOut = true;
    public const int UNDELIVERED = -1001;   // never returned by this build
    public int Undelivered => 0;
    public long ResetCalls => 0;

    private void EnsureDec()
    {
        if (_dctx != IntPtr.Zero) return;
        _dctx = Abi.ak_dec_ctx_new_ChunkElement();   // rule 6: bound to this root; no options exist
        if (_dctx == IntPtr.Zero) throw new InvalidOperationException("ak_dec_ctx_new_ChunkElement returned NULL");
        // D20: the pull family's bits, copied into this root-bound context (every bit: G.Str validates).
        int sp = Abi.ak_dec_set_pvt_ChunkElement(_dctx, Pvt);   // step 5b: the root's one native pvt
        if (sp != 0) throw new InvalidOperationException("ak_dec_set_pvt_ChunkElement: " + sp);
        // D23 / D24: the FSM's own D20 mask, copied once into the context when it is created (set
        // lazily on the first FSM decode, it made one count row depend on which thread decoded).
        int fp = Abi.ak_fsm_set_pvt_ChunkElement(_dctx, FsmPvt);
        if (fp != 0) throw new InvalidOperationException("ak_fsm_set_pvt_ChunkElement: " + fp);
        _drun = (DecRun*)NativeMemory.AllocZeroed((nuint)sizeof(DecRun));
    }

    private int ArmFor(int mode) => mode == -2 ? 0 : throw new NotSupportedException("unknown fields are compiled out of this build (WP5 step 10)");
    private int Disarm(int rc) => rc;

    public ChunkElement Decode(byte[] src, int len) { int rc = TryDecode(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core decode failed: {rc}"); return t; }

    /// The core's code (< 0) on failure; the output is then unspecified and discarded (R-G6).
    public int TryDecode(byte[] src, int len, bool retain, out ChunkElement result) => DecodeArmed(src, len, retain ? -1 : -2, out result);

    /// Step 5b (owner, 2026-10-04): the push vtable, built ONCE per root and kept in native
    /// memory (NativeMemory.Alloc, never freed: one per root for the process), so no decode
    /// writes it and the GC cannot move it. Not a static field of the struct type taken by
    /// address: a non-primitive struct static lives in a boxed object on the GC heap, which
    /// compaction may move, so its address is not stable without a pin. The core only reads
    /// the vtable during the call.
    private static readonly ak_dvt_ChunkElement* Vt = MakeVt();
    private static ak_dvt_ChunkElement* MakeVt()
    {
        var v = (ak_dvt_ChunkElement*)NativeMemory.AllocZeroed((nuint)sizeof(ak_dvt_ChunkElement));
        v->utf8_skip = AkUtf8Skip.ChunkElement_ALL;   // D20: every bit set, G.Str validates (strict)
        v->apply = &ApplyRoot;
        v->add_labels = &Add_labels;
        v->add_attrs = &Add_attrs;
        v->add_inner_marks = &Add_inner_marks;
        v->add_inner_leaves = &Add_inner_leaves;
        return v;
    }
    /// Step 5b: the pull family's bits, once per root in native memory (the setter copies them).
    private static readonly ak_pvt_ChunkElement* Pvt = MakePvt();
    private static ak_pvt_ChunkElement* MakePvt() { var v = (ak_pvt_ChunkElement*)NativeMemory.AllocZeroed((nuint)sizeof(ak_pvt_ChunkElement)); v->utf8_skip = AkUtf8Skip.ChunkElement_ALL; return v; }
    private GCHandle _th;
    private int DecodeArmed(byte[] src, int len, int mode, out ChunkElement result)
    {
        result = null;
        EnsureDec();
        // Step a2 (i): no ak_dec_err_reset / ak_dec_err: ak_decode_* clears the context's
        // sticky slot on entry and returns it (a host failure reported through ak_fail
        // from a reverse call included), so its return value carries every error.
        int ar = ArmFor(mode);
        if (ar != 0) { Disarm(ar); return ar; }
        var target = new ChunkElement();
        // Step a2 (ii): one GCHandle per instance, its Target set for this decode.
        if (!_th.IsAllocated) _th = GCHandle.Alloc(null);
        _th.Target = target;
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                // (NULL, 0) is never handed to the core: an empty buffer is a valid pointer and 0.
                byte* b = len == 0 ? one : b0;
                _drun->Target = GCHandle.ToIntPtr(_th);
                _drun->Buf = b;
                _fwd++;
                rc = Abi.ak_decode_ChunkElement(_dctx, _drun, b, (nuint)len, Vt);
            }
        }
        finally { _th.Target = null; rc = Disarm(rc); }
        if (rc < 0) return rc;
        result = target;
        return 0;
    }

    /// D21 s8 attribution (HARNESS ONLY): the same push decode through another vtable.
    /// kind 0 `parse`: every callback null but `new_<slot>` (NewZero: the core skips a non-leaf
    /// element whose `new_` is null), utf8_skip all bits (as the reference); kind 1 `noop`:
    /// every callback G.Noop (new_: NewZero); kind 2 `parse-validate`: kind 0 with utf8_skip 0
    /// (the core validates every string).
    public static readonly ak_dvt_ChunkElement* VtParse = MakeVtAttr(0), VtNoop = MakeVtAttr(1), VtParseValidate = MakeVtAttr(2);
    private static ak_dvt_ChunkElement* MakeVtAttr(int kind)
    {
        var v = (ak_dvt_ChunkElement*)NativeMemory.AllocZeroed((nuint)sizeof(ak_dvt_ChunkElement));
        v->utf8_skip = kind == 2 ? 0 : AkUtf8Skip.ChunkElement_ALL;
        if (kind == 1) *(void**)&v->apply = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_labels = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_attrs = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_inner_marks = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_inner_leaves = G.NoopPtr;
        return v;
    }
    /// D21 s8 attribution (HARNESS ONLY): DecodeArmed through `vt`; the graph is the bare
    /// root (the callbacks build nothing) and buffers the callbacks did not take are not
    /// UNDELIVERED here (the arena rewinds at the next decode).
    public int DecodeVt(byte[] src, int len, bool retain, ak_dvt_ChunkElement* vt)
    {
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        if (!_th.IsAllocated) _th = GCHandle.Alloc(null);
        int rc;
        fixed (byte* b0 = src)
        fixed (byte* one = One)
        {
            byte* b = len == 0 ? one : b0;
            _drun->Target = GCHandle.ToIntPtr(_th);
            _drun->Buf = b;
            rc = Abi.ak_decode_ChunkElement(_dctx, _drun, b, (nuint)len, vt);
        }
        rc = Disarm(rc);
        return rc == UNDELIVERED ? 0 : rc;
    }
    /// D21 s8 attribution (HARNESS ONLY): the pull family's parse alone (no replay).
    public int ParseOnly(byte[] src, int len, bool retain)
    {
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        int rc;
        fixed (byte* b0 = src)
        fixed (byte* one = One)
            rc = Abi.ak_parse_ChunkElement(_dctx, len == 0 ? one : b0, (nuint)len);
        rc = Disarm(rc);
        return rc == UNDELIVERED ? 0 : rc;
    }

    /// ABI v1 7.1's PULL family: parse into the context's record stream (no reverse
    /// call but grow), then replay it with the same group readers the push callbacks
    /// use. The context is armed exactly as for push.
    public ChunkElement Pull(byte[] src, int len) { int rc = TryPull(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core parse failed: {rc}"); return t; }

    public int TryPull(byte[] src, int len, bool retain, out ChunkElement result)
    {
        result = null;
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        var t = new ChunkElement();
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                byte* b = len == 0 ? one : b0;
                _fwd++;
                rc = Abi.ak_parse_ChunkElement(_dctx, b, (nuint)len);
                if (rc >= 0)
                {
                    byte* recs; nuint rlen;
                    _fwd++;
                    rc = Abi.ak_bdr_ptr(_dctx, &recs, &rlen);
                    if (rc == 0) { try { Replay(t, b, recs, (int)rlen); } catch (DecoderFallbackException) { rc = Abi.AK_ERR_TRANSCODE; } }
                }
            }
        }
        finally { rc = Disarm(rc); }
        if (rc < 0) return rc;
        result = t;
        return 0;
    }

    private const uint OP_APPLY = 1, OP_ADD = 2, OP_NEW = 3, OP_APPLY_ELEM = 4;   // ak_bdr_rec.op
    private static void Replay(ChunkElement t, byte* b, byte* p, int len)
    {
        int at = 0;
        while (len - at >= sizeof(ak_bdr_rec))
        {
            ref var r = ref *(ak_bdr_rec*)(p + at);
            byte* body = p + at + sizeof(ak_bdr_rec);
            at += sizeof(ak_bdr_rec) + (int)r.bytes;
            uint outer = r.slot >> 16, inner = r.slot & 0xFFFF;
            switch (r.op)
            {
                case OP_APPLY: G.D_ChunkElement(ref *(ak_dfix_ChunkElement*)body, t, b); break;
                case OP_ADD when outer == 0 && inner == 1:   // a root-level run
                {
                    var xs = (ak_span*)body; var lst = t.Labels;
                    lst.EnsureCapacity(lst.Count + (int)r.n);   // step 9a: the run's count is known
                    for (int i = 0; i < (int)r.n; i++) lst.Add(G.Str(b, xs[i]));
                    break;
                }
                case OP_ADD when outer == 0 && inner == 2:   // a root-level run
                {
                    var xs = (ak_dfix_ChunkElementAttrsEntry*)body; var lst = t.Attrs;
                    lst.EnsureCapacity(lst.Count + (int)r.n);   // step 9a: the run's count is known
                    // plan: a duplicate key replaces the earlier value.
                    for (int i = 0; i < (int)r.n; i++) lst[G.Str(b, xs[i].key)] = G.Str(b, xs[i].value);
                    break;
                }
                case OP_ADD when outer == 0 && inner == 3:   // a root-level run
                {
                    var xs = (long*)body; var lst = (t.Inner ??= new ChunkInner()).Marks;
                    lst.EnsureCapacity(lst.Count + (int)r.n);   // step 9a: the run's count is known
                    for (int i = 0; i < (int)r.n; i++) lst.Add(xs[i]);
                    break;
                }
                case OP_ADD when outer == 0 && inner == 4:   // a root-level run
                {
                    var xs = (ak_dfix_ChunkLeaf*)body; var lst = (t.Inner ??= new ChunkInner()).Leaves;
                    lst.EnsureCapacity(lst.Count + (int)r.n);   // step 9a: the run's count is known
                    for (int i = 0; i < (int)r.n; i++) { var x = new ChunkLeaf(); G.D_ChunkLeaf(ref xs[i], x, b); lst.Add(x); }
                    break;
                }
                default: break;
            }
        }
    }

    /// FIX-PLAN D23: the FSM decode family. ak_fsm_begin_ChunkElement returns the first
    /// event, ak_fsm_next_ChunkElement each next one, each RETURNING the event's op (>
    /// 0; the root APPLY is the last, the end) or an error (< 0); every event is
    /// consumed (FsmDispatch) before the next call, which may overwrite its payload.
    /// One `fixed` spans begin and every next (the core holds spans into the input
    /// until the end event). Arming, Disarm, retain ownership and the failure path are
    /// pull's; a failed decode's partial object is discarded.
    public ChunkElement Fsm(byte[] src, int len) { int rc = TryFsm(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core FSM decode failed: {rc}"); return t; }
    /// D23: the FSM's own D20 mask (every bit: G.Str validates), native, copied by its setter
    /// (ak_fsm_set_pvt_<Root>) once, when EnsureDec creates the context.
    private static readonly ak_pvt_ChunkElement* FsmPvt = MakeFsmPvt();
    private static ak_pvt_ChunkElement* MakeFsmPvt() { var v = (ak_pvt_ChunkElement*)NativeMemory.AllocZeroed((nuint)sizeof(ak_pvt_ChunkElement)); v->utf8_skip = AkUtf8Skip.ChunkElement_ALL; return v; }

    public int TryFsm(byte[] src, int len, bool retain, out ChunkElement result)
    {
        result = null;
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        var t = new ChunkElement();
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                byte* b = len == 0 ? one : b0;
                ak_fsm_ev ev;
                _fwd++;
                int op = Abi.ak_fsm_begin_ChunkElement(_dctx, b, (nuint)len, &ev);
                try
                {
                    while (op > 0)
                    {
                        if (op == (int)Abi.AK_BDR_APPLY)
                        {
                            // The root group: always the last event, the end.
                            G.D_ChunkElement(ref *(ak_dfix_ChunkElement*)ev.data, t, b);
                            break;
                        }
                        FsmDispatch(t, b, (uint)op, &ev);
                        _fwd++;
                        op = Abi.ak_fsm_next_ChunkElement(_dctx, &ev);
                    }
                    rc = op < 0 ? op : 0;
                }
                catch (DecoderFallbackException) { rc = Abi.AK_ERR_TRANSCODE; }
            }
        }
        finally { rc = Disarm(rc); }
        if (rc < 0) return rc;   // the partial object is dropped
        result = t;
        return 0;
    }

    /// D23: one non-final event, `op` the call's return (NEW, ADD, APPLY_ELEM; the root APPLY is the end event,
    /// handled by TryFsm). slot = outer << 16 | inner, pull's numbering: a root-level run
    /// is (0, slot), a non-leaf slot's element is (slot, 0) and its inner runs (slot, inner).
    private static void FsmDispatch(ChunkElement t, byte* b, uint op, ak_fsm_ev* ev)
    {
        byte* d = (byte*)ev->data;
        switch (op)
        {
            case Abi.AK_BDR_ADD:
                switch (ev->slot)
                {
                    case 1u:   // a root-level run
                    {
                        var xs = (ak_span*)d; var lst = t.Labels; int n = (int)ev->n;
                        lst.EnsureCapacity(lst.Count + n);
                        for (int i = 0; i < n; i++) lst.Add(G.Str(b, xs[i]));
                        return;
                    }
                    case 2u:   // a root-level run
                    {
                        var xs = (ak_dfix_ChunkElementAttrsEntry*)d; var lst = t.Attrs; int n = (int)ev->n;
                        lst.EnsureCapacity(lst.Count + n);
                        for (int i = 0; i < n; i++) lst[G.Str(b, xs[i].key)] = G.Str(b, xs[i].value);
                        return;
                    }
                    case 3u:   // a root-level run
                    {
                        var xs = (long*)d; var lst = (t.Inner ??= new ChunkInner()).Marks; int n = (int)ev->n;
                        lst.EnsureCapacity(lst.Count + n);
                        for (int i = 0; i < n; i++) lst.Add(xs[i]);
                        return;
                    }
                    case 4u:   // a root-level run
                    {
                        var xs = (ak_dfix_ChunkLeaf*)d; var lst = (t.Inner ??= new ChunkInner()).Leaves; int n = (int)ev->n;
                        lst.EnsureCapacity(lst.Count + n);
                        for (int i = 0; i < n; i++) { var x = new ChunkLeaf(); G.D_ChunkLeaf(ref xs[i], x, b); lst.Add(x); }
                        return;
                    }
                }
                return;
        }
    }

    public long PullFootprint() => _dctx == IntPtr.Zero ? 0 : (long)Abi.ak_bdr_footprint(_dctx);
    public AkCounters EncCounters() { AkCounters c; Abi.ak_enc_counters(_ctx, &c); return c; }
    public void EncCountersReset() => Abi.ak_enc_counters_reset(_ctx);
    public AkCounters DecCounters() { AkCounters c; if (_dctx == IntPtr.Zero) return default; Abi.ak_dec_counters(_dctx, &c); return c; }
    public void DecCountersReset() { if (_dctx != IntPtr.Zero) Abi.ak_dec_counters_reset(_dctx); }

    public void Dispose()
    {
        if (_ctx != IntPtr.Zero) { Abi.ak_enc_ctx_free(_ctx); _ctx = IntPtr.Zero; }
        if (_dctx != IntPtr.Zero) { Abi.ak_dec_ctx_free(_dctx); _dctx = IntPtr.Zero; }
        if (_th.IsAllocated) _th.Free();
        _st.Dispose();
        if (_run != null)
        {
            NativeMemory.Free(_run->S_labels);
            NativeMemory.Free(_run->S_attrs);
            NativeMemory.Free(_run->S_inner_marks);
            NativeMemory.Free(_run->S_inner_leaves);
            NativeMemory.Free(_run); _run = null;
        }
        if (_drun != null) { NativeMemory.Free(_drun); _drun = null; }
    }
}

[StructLayout(LayoutKind.Sequential)]
public unsafe struct Run_ChunkedResponse
{
    public int Chunk;
    public int Retain;
    public void* S_items; public int N_items;
    public void* I_items_labels; public int* O_items_labels; public int* C_items_labels;
    public void* I_items_attrs; public int* O_items_attrs; public int* C_items_attrs;
    public void* I_items_inner_marks; public int* O_items_inner_marks; public int* C_items_inner_marks;
    public void* I_items_inner_leaves; public int* O_items_inner_leaves; public int* C_items_inner_leaves;
}

/// core-ffi for `ChunkedResponse`: every group, slot and entry point from the plan.
public sealed unsafe class CoreFfi_ChunkedResponse : IDisposable
{
    private IntPtr _ctx, _dctx;
    private readonly Stage _st;
    private Run_ChunkedResponse* _run;
    private DecRun* _drun;
    public int Chunk;
    /// Counted where each crossing happens (R5). Static: an [UnmanagedCallersOnly]
    /// callback cannot reach an instance; one arm at a time.
    private static long _fwd, _rev;
    public long ForwardCalls => _fwd;
    public long ReverseCalls => _rev;
    public void CallsReset() { _fwd = 0; _rev = 0; }
    private int _cap_items;
    private int _cap_items_labels, _capo_items_labels;
    private int _cap_items_attrs, _capo_items_attrs;
    private int _cap_items_inner_marks, _capo_items_inner_marks;
    private int _cap_items_inner_leaves, _capo_items_inner_leaves;
    private ak_evt_ChunkElement* _evt_items;

    public CoreFfi_ChunkedResponse(bool utf16 = false)
    {
        _ctx = Abi.ak_enc_ctx_new();
