    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static int Loop_items_inner_leaves(IntPtr ctx, void* obj, long token)
    {
        _rev++;
        try
        {
            var run = (Run_ChunkedResponse*)obj;
            int e = (int)token;
            int n = run->C_items_inner_leaves[e];
