            if (Stage.DeferNow != 0) return PinElems_items_inner_leaves(ctx, (ak_efix_ChunkLeaf*)run->I_items_inner_leaves + run->O_items_inner_leaves[e], _pinSrc.Items[e].Inner?.Leaves, n);
            _fwd++;
            return Abi.ak_elem_ChunkLeaf(ctx, (ak_efix_ChunkLeaf*)((ak_efix_ChunkLeaf*)run->I_items_inner_leaves + run->O_items_inner_leaves[e]), n);
        }
        catch { return Abi.AK_ERR_HOST; }
    }

    public int Fill(ChunkedResponse src) { Go(src, false, false, out _, out _); return 0; }
    public void Encode(ChunkedResponse src, out byte* p, out int len) { int rc = Go(src, false, true, out p, out len); if (rc < 0) throw new InvalidOperationException($"core encode failed: {rc}"); }
    public int TryEncode(ChunkedResponse src, bool retain, out byte* p, out int len) => Go(src, retain, true, out p, out len);
    /// ABI v1 section 9's move path (WP8): encode and leave the output IN the encode context,
    /// no ak_enc_take, for ak_call_unary_enc / ak_call_send_enc to move as the request body.
    public int EncodeInto(ChunkedResponse src, bool retain)
    {
        _keep = true;
        try { return Go(src, retain, true, out _, out _); }
        finally { _keep = false; }
    }
    /// A copy of the bytes an EncodeInto left in the context (ak_enc_take reads them without
    /// consuming them); for checks, never on a timed path.
    public byte[] ContextBytes()
    {
        byte* bp; nuint blen;
        int tk = Abi.ak_enc_take(_ctx, &bp, &blen);
        if (tk != 0) throw new InvalidOperationException($"core encode failed: {tk}");
        return new ReadOnlySpan<byte>(bp, (int)blen).ToArray();
    }
    /// The encode context, for the move path's entries.
    public IntPtr EncContext => _ctx;
    private bool _keep;
    public byte[] EncodeToArray(ChunkedResponse src, bool retain = false)
    {
        int rc = Go(src, retain, true, out byte* p, out int len);
        if (rc < 0) throw new InvalidOperationException($"core encode failed: {rc}");
        var a = new byte[len];
        new ReadOnlySpan<byte>(p, len).CopyTo(a);
        return a;
    }

    private int Go(ChunkedResponse src, bool retain, bool call, out byte* outPtr, out int outLen)
    {
        outPtr = null; outLen = 0;
        Abi.ak_enc_reset(_ctx);
        _st.Reset();
        int __d = Stage.Defer;   // E1R / E1C: read once; the default path tests this local only
        long __mk0 = 0, __pt0 = 0;
        if (__d != 0) { __mk0 = Stage.Marked; __pt0 = Stage.Patched; }   // this encode's marks and patches
        _run->Chunk = Chunk;
        if (retain) throw new NotSupportedException("unknown fields are compiled out of this build (WP5 step 10): no ak_uencode");
        {
            var lst = src.Items;
            int n = lst == null ? 0 : lst.Count;
            _run->N_items = n;
            Arr.Ensure(ref _run->S_items, ref _cap_items, n, sizeof(ak_efix_ChunkElement));
            for (int i = 0; i < n; i++)
            {
                G.E_ChunkElement(ref ((ak_efix_ChunkElement*)_run->S_items)[i], lst[i], _st);
            }
            {
                int tot = 0;
                for (int i = 0; i < n; i++) { var il = lst[i].Labels; tot += il == null ? 0 : il.Count; }
                Arr.Ensure(ref _run->I_items_labels, ref _cap_items_labels, tot, sizeof(ak_str));
                { void* po = _run->O_items_labels; int c0 = _capo_items_labels; Arr.Ensure(ref po, ref c0, n, sizeof(int)); _run->O_items_labels = (int*)po;
                  void* pc = _run->C_items_labels; int c1 = _capo_items_labels; Arr.Ensure(ref pc, ref c1, n, sizeof(int)); _run->C_items_labels = (int*)pc; _capo_items_labels = c1; }
                int bi = 0;
                for (int i = 0; i < n; i++)
                {
                    var il = lst[i].Labels;
                    int m2 = il == null ? 0 : il.Count;
                    _run->O_items_labels[i] = bi; _run->C_items_labels[i] = m2;
                    for (int j = 0; j < m2; j++, bi++)
                    {
                        ((ak_str*)_run->I_items_labels)[bi] = _st.Str(il[j]);
                    }
                }
            }
            {
                int tot = 0;
                for (int i = 0; i < n; i++) { var il = lst[i].Attrs; tot += il == null ? 0 : il.Count; }
                Arr.Ensure(ref _run->I_items_attrs, ref _cap_items_attrs, tot, sizeof(ak_efix_ChunkElementAttrsEntry));
                { void* po = _run->O_items_attrs; int c0 = _capo_items_attrs; Arr.Ensure(ref po, ref c0, n, sizeof(int)); _run->O_items_attrs = (int*)po;
                  void* pc = _run->C_items_attrs; int c1 = _capo_items_attrs; Arr.Ensure(ref pc, ref c1, n, sizeof(int)); _run->C_items_attrs = (int*)pc; _capo_items_attrs = c1; }
                int bi = 0;
                for (int i = 0; i < n; i++)
                {
                    var il = lst[i].Attrs;
                    int m2 = il == null ? 0 : il.Count;
                    _run->O_items_attrs[i] = bi; _run->C_items_attrs[i] = m2;
                    for (int j = 0; j < m2; j++) { var kv = il.At(j); { ref var e = ref ((ak_efix_ChunkElementAttrsEntry*)_run->I_items_attrs)[bi]; e = default; e.key = _st.Str(kv.Key); e.value = _st.Str(kv.Value); } bi++; }
                }
            }
            {
                int tot = 0;
                for (int i = 0; i < n; i++) { var il = lst[i].Inner?.Marks; tot += il == null ? 0 : il.Count; }
                Arr.Ensure(ref _run->I_items_inner_marks, ref _cap_items_inner_marks, tot, sizeof(long));
                { void* po = _run->O_items_inner_marks; int c0 = _capo_items_inner_marks; Arr.Ensure(ref po, ref c0, n, sizeof(int)); _run->O_items_inner_marks = (int*)po;
                  void* pc = _run->C_items_inner_marks; int c1 = _capo_items_inner_marks; Arr.Ensure(ref pc, ref c1, n, sizeof(int)); _run->C_items_inner_marks = (int*)pc; _capo_items_inner_marks = c1; }
                int bi = 0;
                for (int i = 0; i < n; i++)
                {
                    var il = lst[i].Inner?.Marks;
                    int m2 = il == null ? 0 : il.Count;
                    _run->O_items_inner_marks[i] = bi; _run->C_items_inner_marks[i] = m2;
                    for (int j = 0; j < m2; j++, bi++)
                    {
                        ((long*)_run->I_items_inner_marks)[bi] = il[j];
                    }
                }
            }
            {
                int tot = 0;
                for (int i = 0; i < n; i++) { var il = lst[i].Inner?.Leaves; tot += il == null ? 0 : il.Count; }
                Arr.Ensure(ref _run->I_items_inner_leaves, ref _cap_items_inner_leaves, tot, sizeof(ak_efix_ChunkLeaf));
                { void* po = _run->O_items_inner_leaves; int c0 = _capo_items_inner_leaves; Arr.Ensure(ref po, ref c0, n, sizeof(int)); _run->O_items_inner_leaves = (int*)po;
                  void* pc = _run->C_items_inner_leaves; int c1 = _capo_items_inner_leaves; Arr.Ensure(ref pc, ref c1, n, sizeof(int)); _run->C_items_inner_leaves = (int*)pc; _capo_items_inner_leaves = c1; }
                int bi = 0;
                for (int i = 0; i < n; i++)
                {
                    var il = lst[i].Inner?.Leaves;
                    int m2 = il == null ? 0 : il.Count;
                    _run->O_items_inner_leaves[i] = bi; _run->C_items_inner_leaves[i] = m2;
                    for (int j = 0; j < m2; j++, bi++)
                    {
                        G.E_ChunkLeaf(ref ((ak_efix_ChunkLeaf*)_run->I_items_inner_leaves)[bi], il[j], _st);
                    }
