    }

    [StructLayout(LayoutKind.Sequential)]
    private struct DecRun { public IntPtr Target; public byte* Buf; }

    private static ChunkedResponse Tgt(void* obj) => (ChunkedResponse)GCHandle.FromIntPtr(((DecRun*)obj)->Target).Target;

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void ApplyRoot(IntPtr ctx, void* obj, ak_dfix_ChunkedResponse* fix)
    {
        _rev++;
        try { if (G.PlantHostFail == 1) throw new InvalidOperationException("planted host failure (apply)"); G.D_ChunkedResponse(ref *fix, Tgt(obj), ((DecRun*)obj)->Buf); }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static long New_items(IntPtr ctx, void* obj)
    {
        _rev++;
        try { if (G.PlantHostFail == 2) throw new InvalidOperationException("planted host failure (new)"); var lst = Tgt(obj).Items; lst.Add(new ChunkElement()); return lst.Count - 1; }
        catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); return -1; }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Apply_items(IntPtr ctx, void* obj, long token, ak_dfix_ChunkElement* fix)
    {
        _rev++;
        try { var lst = Tgt(obj).Items; G.D_ChunkElement(ref *fix, lst[(int)token], ((DecRun*)obj)->Buf); }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_items_labels(IntPtr ctx, void* obj, long token, ak_span* xs, int n)
    {
        _rev++;
        try
        {
            byte* b = ((DecRun*)obj)->Buf;
            var e = Tgt(obj).Items[(int)token];
            var il = e.Labels;
            il.EnsureCapacity(il.Count + n);   // step 9a: the run's count is known
            for (int k = 0; k < n; k++) il.Add(G.Str(b, xs[k]));
        }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_items_attrs(IntPtr ctx, void* obj, long token, ak_dfix_ChunkElementAttrsEntry* xs, int n)
    {
        _rev++;
        try
        {
            byte* b = ((DecRun*)obj)->Buf;
            var e = Tgt(obj).Items[(int)token];
            var il = e.Attrs;
            il.EnsureCapacity(il.Count + n);   // step 9a: the run's count is known
            // plan: a duplicate key replaces the earlier value.
            for (int k = 0; k < n; k++) il[G.Str(b, xs[k].key)] = G.Str(b, xs[k].value);
        }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_items_inner_marks(IntPtr ctx, void* obj, long token, long* xs, int n)
    {
        _rev++;
        try
        {
            byte* b = ((DecRun*)obj)->Buf;
            var e = Tgt(obj).Items[(int)token];
            var il = (e.Inner ??= new ChunkInner()).Marks;
            il.EnsureCapacity(il.Count + n);   // step 9a: the run's count is known
            for (int k = 0; k < n; k++) il.Add(xs[k]);
        }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_items_inner_leaves(IntPtr ctx, void* obj, long token, ak_dfix_ChunkLeaf* xs, int n)
    {
        _rev++;
        try
        {
            byte* b = ((DecRun*)obj)->Buf;
            var e = Tgt(obj).Items[(int)token];
            var il = (e.Inner ??= new ChunkInner()).Leaves;
            il.EnsureCapacity(il.Count + n);   // step 9a: the run's count is known
            for (int k = 0; k < n; k++) { var x = new ChunkLeaf(); G.D_ChunkLeaf(ref xs[k], x, b); il.Add(x); }
        }
        catch (DecoderFallbackException) { Abi.ak_fail(ctx, Abi.AK_ERR_TRANSCODE, null, 0); } catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    private static readonly byte[] One = new byte[1];

    /// WP5 step 10: this build has unknown fields COMPILED OUT (no options, no resets).
    public const bool UnknownCompiledOut = true;
    public const int UNDELIVERED = -1001;   // never returned by this build
    public int Undelivered => 0;
    public long ResetCalls => 0;

    private void EnsureDec()
    {
        if (_dctx != IntPtr.Zero) return;
        _dctx = Abi.ak_dec_ctx_new_ChunkedResponse();   // rule 6: bound to this root; no options exist
        if (_dctx == IntPtr.Zero) throw new InvalidOperationException("ak_dec_ctx_new_ChunkedResponse returned NULL");
        // D20: the pull family's bits, copied into this root-bound context (every bit: G.Str validates).
        int sp = Abi.ak_dec_set_pvt_ChunkedResponse(_dctx, Pvt);   // step 5b: the root's one native pvt
        if (sp != 0) throw new InvalidOperationException("ak_dec_set_pvt_ChunkedResponse: " + sp);
        // D23 / D24: the FSM's own D20 mask, copied once into the context when it is created (set
        // lazily on the first FSM decode, it made one count row depend on which thread decoded).
        int fp = Abi.ak_fsm_set_pvt_ChunkedResponse(_dctx, FsmPvt);
        if (fp != 0) throw new InvalidOperationException("ak_fsm_set_pvt_ChunkedResponse: " + fp);
        _drun = (DecRun*)NativeMemory.AllocZeroed((nuint)sizeof(DecRun));
    }

    private int ArmFor(int mode) => mode == -2 ? 0 : throw new NotSupportedException("unknown fields are compiled out of this build (WP5 step 10)");
    private int Disarm(int rc) => rc;

    public ChunkedResponse Decode(byte[] src, int len) { int rc = TryDecode(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core decode failed: {rc}"); return t; }

    /// The core's code (< 0) on failure; the output is then unspecified and discarded (R-G6).
    public int TryDecode(byte[] src, int len, bool retain, out ChunkedResponse result) => DecodeArmed(src, len, retain ? -1 : -2, out result);

    /// Step 5b (owner, 2026-10-04): the push vtable, built ONCE per root and kept in native
    /// memory (NativeMemory.Alloc, never freed: one per root for the process), so no decode
    /// writes it and the GC cannot move it. Not a static field of the struct type taken by
    /// address: a non-primitive struct static lives in a boxed object on the GC heap, which
    /// compaction may move, so its address is not stable without a pin. The core only reads
    /// the vtable during the call.
    private static readonly ak_dvt_ChunkedResponse* Vt = MakeVt();
    private static ak_dvt_ChunkedResponse* MakeVt()
    {
        var v = (ak_dvt_ChunkedResponse*)NativeMemory.AllocZeroed((nuint)sizeof(ak_dvt_ChunkedResponse));
        v->utf8_skip = AkUtf8Skip.ChunkedResponse_ALL;   // D20: every bit set, G.Str validates (strict)
        v->apply = &ApplyRoot;
        v->new_items = &New_items;
        v->apply_items = &Apply_items;
        v->add_items_labels = &Add_items_labels;
        v->add_items_attrs = &Add_items_attrs;
        v->add_items_inner_marks = &Add_items_inner_marks;
        v->add_items_inner_leaves = &Add_items_inner_leaves;
        return v;
    }
    /// Step 5b: the pull family's bits, once per root in native memory (the setter copies them).
    private static readonly ak_pvt_ChunkedResponse* Pvt = MakePvt();
    private static ak_pvt_ChunkedResponse* MakePvt() { var v = (ak_pvt_ChunkedResponse*)NativeMemory.AllocZeroed((nuint)sizeof(ak_pvt_ChunkedResponse)); v->utf8_skip = AkUtf8Skip.ChunkedResponse_ALL; return v; }
    private GCHandle _th;
    private int DecodeArmed(byte[] src, int len, int mode, out ChunkedResponse result)
    {
        result = null;
        EnsureDec();
        // Step a2 (i): no ak_dec_err_reset / ak_dec_err: ak_decode_* clears the context's
        // sticky slot on entry and returns it (a host failure reported through ak_fail
        // from a reverse call included), so its return value carries every error.
        int ar = ArmFor(mode);
        if (ar != 0) { Disarm(ar); return ar; }
        var target = new ChunkedResponse();
        // Step a2 (ii): one GCHandle per instance, its Target set for this decode.
        if (!_th.IsAllocated) _th = GCHandle.Alloc(null);
        _th.Target = target;
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                // (NULL, 0) is never handed to the core: an empty buffer is a valid pointer and 0.
                byte* b = len == 0 ? one : b0;
                _drun->Target = GCHandle.ToIntPtr(_th);
                _drun->Buf = b;
                _fwd++;
                rc = Abi.ak_decode_ChunkedResponse(_dctx, _drun, b, (nuint)len, Vt);
            }
        }
        finally { _th.Target = null; rc = Disarm(rc); }
        if (rc < 0) return rc;
        result = target;
        return 0;
    }

    /// D21 s8 attribution (HARNESS ONLY): the same push decode through another vtable.
    /// kind 0 `parse`: every callback null but `new_<slot>` (NewZero: the core skips a non-leaf
    /// element whose `new_` is null), utf8_skip all bits (as the reference); kind 1 `noop`:
    /// every callback G.Noop (new_: NewZero); kind 2 `parse-validate`: kind 0 with utf8_skip 0
    /// (the core validates every string).
    public static readonly ak_dvt_ChunkedResponse* VtParse = MakeVtAttr(0), VtNoop = MakeVtAttr(1), VtParseValidate = MakeVtAttr(2);
    private static ak_dvt_ChunkedResponse* MakeVtAttr(int kind)
    {
        var v = (ak_dvt_ChunkedResponse*)NativeMemory.AllocZeroed((nuint)sizeof(ak_dvt_ChunkedResponse));
        v->utf8_skip = kind == 2 ? 0 : AkUtf8Skip.ChunkedResponse_ALL;
        if (kind == 1) *(void**)&v->apply = G.NoopPtr;
        *(void**)&v->new_items = G.NewZeroPtr;
        if (kind == 1) *(void**)&v->apply_items = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_items_labels = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_items_attrs = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_items_inner_marks = G.NoopPtr;
        if (kind == 1) *(void**)&v->add_items_inner_leaves = G.NoopPtr;
        return v;
    }
    /// D21 s8 attribution (HARNESS ONLY): DecodeArmed through `vt`; the graph is the bare
    /// root (the callbacks build nothing) and buffers the callbacks did not take are not
    /// UNDELIVERED here (the arena rewinds at the next decode).
    public int DecodeVt(byte[] src, int len, bool retain, ak_dvt_ChunkedResponse* vt)
    {
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        if (!_th.IsAllocated) _th = GCHandle.Alloc(null);
        int rc;
        fixed (byte* b0 = src)
        fixed (byte* one = One)
        {
            byte* b = len == 0 ? one : b0;
            _drun->Target = GCHandle.ToIntPtr(_th);
            _drun->Buf = b;
            rc = Abi.ak_decode_ChunkedResponse(_dctx, _drun, b, (nuint)len, vt);
        }
        rc = Disarm(rc);
        return rc == UNDELIVERED ? 0 : rc;
    }
    /// D21 s8 attribution (HARNESS ONLY): the pull family's parse alone (no replay).
    public int ParseOnly(byte[] src, int len, bool retain)
    {
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        int rc;
        fixed (byte* b0 = src)
        fixed (byte* one = One)
            rc = Abi.ak_parse_ChunkedResponse(_dctx, len == 0 ? one : b0, (nuint)len);
        rc = Disarm(rc);
        return rc == UNDELIVERED ? 0 : rc;
    }

    /// ABI v1 7.1's PULL family: parse into the context's record stream (no reverse
    /// call but grow), then replay it with the same group readers the push callbacks
    /// use. The context is armed exactly as for push.
    public ChunkedResponse Pull(byte[] src, int len) { int rc = TryPull(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core parse failed: {rc}"); return t; }

    public int TryPull(byte[] src, int len, bool retain, out ChunkedResponse result)
    {
        result = null;
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        var t = new ChunkedResponse();
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                byte* b = len == 0 ? one : b0;
                _fwd++;
                rc = Abi.ak_parse_ChunkedResponse(_dctx, b, (nuint)len);
                if (rc >= 0)
                {
                    byte* recs; nuint rlen;
                    _fwd++;
                    rc = Abi.ak_bdr_ptr(_dctx, &recs, &rlen);
                    if (rc == 0) { try { Replay(t, b, recs, (int)rlen); } catch (DecoderFallbackException) { rc = Abi.AK_ERR_TRANSCODE; } }
                }
            }
        }
        finally { rc = Disarm(rc); }
        if (rc < 0) return rc;
        result = t;
        return 0;
    }

    private const uint OP_APPLY = 1, OP_ADD = 2, OP_NEW = 3, OP_APPLY_ELEM = 4;   // ak_bdr_rec.op
    private static void Replay(ChunkedResponse t, byte* b, byte* p, int len)
    {
        int at = 0;
        while (len - at >= sizeof(ak_bdr_rec))
        {
            ref var r = ref *(ak_bdr_rec*)(p + at);
            byte* body = p + at + sizeof(ak_bdr_rec);
            at += sizeof(ak_bdr_rec) + (int)r.bytes;
            uint outer = r.slot >> 16, inner = r.slot & 0xFFFF;
            switch (r.op)
            {
                case OP_APPLY: G.D_ChunkedResponse(ref *(ak_dfix_ChunkedResponse*)body, t, b); break;
                case OP_NEW when outer == 1: t.Items.Add(new ChunkElement()); break;
                case OP_APPLY_ELEM when outer == 1: G.D_ChunkElement(ref *(ak_dfix_ChunkElement*)body, t.Items[(int)r.token], b); break;
                case OP_ADD when outer == 1 && inner == 1:
                {
                    var xs = (ak_span*)body; var e = t.Items[(int)r.token]; var il = e.Labels;
                    il.EnsureCapacity(il.Count + (int)r.n);   // step 9a: the run's count is known
                    for (int k = 0; k < (int)r.n; k++) il.Add(G.Str(b, xs[k]));
                    break;
                }
                case OP_ADD when outer == 1 && inner == 2:
                {
                    var xs = (ak_dfix_ChunkElementAttrsEntry*)body; var e = t.Items[(int)r.token]; var il = e.Attrs;
                    il.EnsureCapacity(il.Count + (int)r.n);   // step 9a: the run's count is known
                    // plan: a duplicate key replaces the earlier value.
                    for (int k = 0; k < (int)r.n; k++) il[G.Str(b, xs[k].key)] = G.Str(b, xs[k].value);
                    break;
                }
                case OP_ADD when outer == 1 && inner == 3:
                {
                    var xs = (long*)body; var e = t.Items[(int)r.token]; var il = (e.Inner ??= new ChunkInner()).Marks;
                    il.EnsureCapacity(il.Count + (int)r.n);   // step 9a: the run's count is known
                    for (int k = 0; k < (int)r.n; k++) il.Add(xs[k]);
                    break;
                }
                case OP_ADD when outer == 1 && inner == 4:
                {
                    var xs = (ak_dfix_ChunkLeaf*)body; var e = t.Items[(int)r.token]; var il = (e.Inner ??= new ChunkInner()).Leaves;
                    il.EnsureCapacity(il.Count + (int)r.n);   // step 9a: the run's count is known
                    for (int k = 0; k < (int)r.n; k++) { var x = new ChunkLeaf(); G.D_ChunkLeaf(ref xs[k], x, b); il.Add(x); }
                    break;
                }
                default: break;
            }
        }
    }

    /// FIX-PLAN D23: the FSM decode family. ak_fsm_begin_ChunkedResponse returns the
    /// first event, ak_fsm_next_ChunkedResponse each next one, each RETURNING the
    /// event's op (> 0; the root APPLY is the last, the end) or an error (< 0); every
    /// event is consumed (FsmDispatch) before the next call, which may overwrite its
    /// payload. One `fixed` spans begin and every next (the core holds spans into the
    /// input until the end event). Arming, Disarm, retain ownership and the failure
    /// path are pull's; a failed decode's partial object is discarded.
    public ChunkedResponse Fsm(byte[] src, int len) { int rc = TryFsm(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core FSM decode failed: {rc}"); return t; }
    /// D23: the FSM's own D20 mask (every bit: G.Str validates), native, copied by its setter
    /// (ak_fsm_set_pvt_<Root>) once, when EnsureDec creates the context.
    private static readonly ak_pvt_ChunkedResponse* FsmPvt = MakeFsmPvt();
    private static ak_pvt_ChunkedResponse* MakeFsmPvt() { var v = (ak_pvt_ChunkedResponse*)NativeMemory.AllocZeroed((nuint)sizeof(ak_pvt_ChunkedResponse)); v->utf8_skip = AkUtf8Skip.ChunkedResponse_ALL; return v; }

    public int TryFsm(byte[] src, int len, bool retain, out ChunkedResponse result)
    {
        result = null;
        EnsureDec();
        int ar = ArmFor(retain ? -1 : -2);
        if (ar != 0) { Disarm(ar); return ar; }
        var t = new ChunkedResponse();
        int rc = Abi.AK_ERR_HOST;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                byte* b = len == 0 ? one : b0;
                ak_fsm_ev ev;
                _fwd++;
                int op = Abi.ak_fsm_begin_ChunkedResponse(_dctx, b, (nuint)len, &ev);
                try
                {
                    while (op > 0)
                    {
                        if (op == (int)Abi.AK_BDR_APPLY)
                        {
                            // The root group: always the last event, the end.
                            G.D_ChunkedResponse(ref *(ak_dfix_ChunkedResponse*)ev.data, t, b);
                            break;
                        }
                        FsmDispatch(t, b, (uint)op, &ev);
                        _fwd++;
                        op = Abi.ak_fsm_next_ChunkedResponse(_dctx, &ev);
                    }
                    rc = op < 0 ? op : 0;
                }
                catch (DecoderFallbackException) { rc = Abi.AK_ERR_TRANSCODE; }
            }
        }
        finally { rc = Disarm(rc); }
        if (rc < 0) return rc;   // the partial object is dropped
        result = t;
        return 0;
    }

    /// D23: one non-final event, `op` the call's return (NEW, ADD, APPLY_ELEM; the root APPLY is the end event,
    /// handled by TryFsm). slot = outer << 16 | inner, pull's numbering: a root-level run
    /// is (0, slot), a non-leaf slot's element is (slot, 0) and its inner runs (slot, inner).
    private static void FsmDispatch(ChunkedResponse t, byte* b, uint op, ak_fsm_ev* ev)
    {
        byte* d = (byte*)ev->data;
        switch (op)
        {
            case Abi.AK_BDR_NEW:
                switch (ev->slot >> 16)
                {
                    case 1: t.Items.Add(new ChunkElement()); return;
                }
                return;
            case Abi.AK_BDR_APPLY_ELEM:
                switch (ev->slot >> 16)
                {
                    case 1: G.D_ChunkElement(ref *(ak_dfix_ChunkElement*)d, t.Items[(int)ev->token], b); return;
                }
                return;
            case Abi.AK_BDR_ADD:
                switch (ev->slot)
                {
                    case 65537u:   // slot 1's element, inner run 1
                    {
                        var xs = (ak_span*)d; var e = t.Items[(int)ev->token]; var il = e.Labels; int n = (int)ev->n;
                        il.EnsureCapacity(il.Count + n);
                        for (int k = 0; k < n; k++) il.Add(G.Str(b, xs[k]));
                        return;
                    }
                    case 65538u:   // slot 1's element, inner run 2
                    {
                        var xs = (ak_dfix_ChunkElementAttrsEntry*)d; var e = t.Items[(int)ev->token]; var il = e.Attrs; int n = (int)ev->n;
                        il.EnsureCapacity(il.Count + n);
                        for (int k = 0; k < n; k++) il[G.Str(b, xs[k].key)] = G.Str(b, xs[k].value);
                        return;
                    }
                    case 65539u:   // slot 1's element, inner run 3
                    {
                        var xs = (long*)d; var e = t.Items[(int)ev->token]; var il = (e.Inner ??= new ChunkInner()).Marks; int n = (int)ev->n;
                        il.EnsureCapacity(il.Count + n);
                        for (int k = 0; k < n; k++) il.Add(xs[k]);
                        return;
                    }
                    case 65540u:   // slot 1's element, inner run 4
                    {
                        var xs = (ak_dfix_ChunkLeaf*)d; var e = t.Items[(int)ev->token]; var il = (e.Inner ??= new ChunkInner()).Leaves; int n = (int)ev->n;
                        il.EnsureCapacity(il.Count + n);
                        for (int k = 0; k < n; k++) { var x = new ChunkLeaf(); G.D_ChunkLeaf(ref xs[k], x, b); il.Add(x); }
                        return;
                    }
                }
                return;
        }
    }

    public long PullFootprint() => _dctx == IntPtr.Zero ? 0 : (long)Abi.ak_bdr_footprint(_dctx);
    public AkCounters EncCounters() { AkCounters c; Abi.ak_enc_counters(_ctx, &c); return c; }
    public void EncCountersReset() => Abi.ak_enc_counters_reset(_ctx);
    public AkCounters DecCounters() { AkCounters c; if (_dctx == IntPtr.Zero) return default; Abi.ak_dec_counters(_dctx, &c); return c; }
    public void DecCountersReset() { if (_dctx != IntPtr.Zero) Abi.ak_dec_counters_reset(_dctx); }

    public void Dispose()
    {
        if (_ctx != IntPtr.Zero) { Abi.ak_enc_ctx_free(_ctx); _ctx = IntPtr.Zero; }
        if (_dctx != IntPtr.Zero) { Abi.ak_dec_ctx_free(_dctx); _dctx = IntPtr.Zero; }
        if (_th.IsAllocated) _th.Free();
        _st.Dispose();
        if (_run != null)
        {
            NativeMemory.Free(_run->S_items);
            NativeMemory.Free(_run->I_items_labels); NativeMemory.Free(_run->O_items_labels); NativeMemory.Free(_run->C_items_labels);
            NativeMemory.Free(_run->I_items_attrs); NativeMemory.Free(_run->O_items_attrs); NativeMemory.Free(_run->C_items_attrs);
            NativeMemory.Free(_run->I_items_inner_marks); NativeMemory.Free(_run->O_items_inner_marks); NativeMemory.Free(_run->C_items_inner_marks);
            NativeMemory.Free(_run->I_items_inner_leaves); NativeMemory.Free(_run->O_items_inner_leaves); NativeMemory.Free(_run->C_items_inner_leaves);
            NativeMemory.Free(_run); _run = null;
        }
        if (_evt_items != null) { NativeMemory.Free(_evt_items); _evt_items = null; }
        if (_drun != null) { NativeMemory.Free(_drun); _drun = null; }
    }
}

