    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    private static nint RootPinR_e(Run_LeafElement* _run, IntPtr _ctx, ak_evt_LeafElement* vt, ak_efix_LeafElement* __g, LeafElement src)
    {
