                        return;
                    }
                    case 2u:   // a root-level run
                    {
                        var xs = (ak_span*)d; var lst = t.Texts; int n = (int)ev->n;
                        lst.EnsureCapacity(lst.Count + n);
                        for (int i = 0; i < n; i++) lst.Add(G.Str(b, xs[i]));
                        return;
                    }
                }
                return;
        }
    }

